// GERADO por scripts/embed-assets.ts — não edite à mão. Rode `bun run embed`.
export interface EmbeddedAsset { contentType: string; text?: string; binary?: Buffer }
export const assets: Record<string, EmbeddedAsset> = {
  "index.html": { contentType: "text/html; charset=utf-8", text: "<!DOCTYPE html>\r\n<html lang=\"pt-BR\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>Gestor de Tráfego Pago</title>\r\n<style>\r\n:root{--bg:#EBEFED;--surface:#fff;--ink:#16201C;--muted:#647570;--line:#D8DFDC;--btn:#16201C;--btn-ink:#fff;\r\n--good:#0B8A4C;--good-bg:#D9F2E4;--good-seg:#2FBF7A;--ok:#0E76B8;--ok-bg:#D8ECF9;--ok-seg:#3AA6E6;\r\n--warn:#8A5F00;--warn-bg:#F6E8BE;--warn-seg:#E2AE1F;--bad:#B72929;--bad-bg:#F8DADA;--bad-seg:#E5595B;--wait-bg:#E3E9E6;--wait:#5D6D68}\r\n*{box-sizing:border-box}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font:400 14px/1.45 system-ui,\"Segoe UI\",Roboto,Arial,sans-serif;padding:0}\r\n.app{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:100vh}\r\n.side{background:var(--surface);border-right:1px solid var(--line);padding:18px 12px;display:flex;flex-direction:column;gap:2px;position:sticky;top:0;height:100vh}\r\n.brand{font-weight:800;font-size:17px;padding:4px 10px 16px}\r\n.nav{display:flex;flex-direction:column;gap:2px}\r\n.nav a{padding:9px 10px;border-radius:9px;text-decoration:none;color:#3A4843;font-weight:600}\r\n.nav a[aria-current=\"page\"]{background:var(--btn);color:var(--btn-ink)}\r\n.main{padding:26px 28px 56px;min-width:0}\r\n.wrap{max-width:1100px;margin:0 auto}\r\n.ph{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:16px}\r\n.ph h1{margin:0;font-size:28px}\r\n.sub{color:var(--muted);font-size:13px;margin:4px 0 0}\r\n.panel{background:var(--surface);border:1px solid var(--line);border-radius:14px;margin-bottom:16px}\r\n.panel-b{padding:18px}\r\n.fb{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}\r\n.ctl{display:inline-flex;align-items:center;gap:8px;height:38px;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}\r\n.ctl input,.ctl select{border:0;background:transparent;outline:0}\r\n.ctl.search{min-width:240px}.ctl.search input{flex:1}\r\n.btn{display:inline-flex;align-items:center;gap:8px;height:38px;padding:0 14px;border-radius:9px;border:1px solid var(--btn);background:var(--btn);color:var(--btn-ink);font-weight:700;cursor:pointer;text-decoration:none}\r\n.btn.ghost{background:transparent;color:var(--ink);border-color:var(--line)}\r\n.btn:disabled{opacity:.4;cursor:not-allowed}\r\n.in{height:40px;width:100%;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}\r\ntextarea.in{height:auto;min-height:80px;padding:10px 12px;resize:vertical}\r\n.in.err{border-color:var(--bad)}\r\n.fld{display:grid;gap:6px;margin-bottom:14px}.fld>label{font-weight:700}\r\n.hint{font-size:12.5px;color:var(--muted)}\r\n.err-msg{font-size:13px;color:var(--bad);font-weight:700}\r\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:9px;padding:3px;background:#F4F7F6;gap:2px}\r\n.seg button{height:32px;padding:0 14px;border:0;border-radius:7px;background:transparent;cursor:pointer;font-weight:600}\r\n.seg button[aria-pressed=\"true\"]{background:var(--surface);box-shadow:0 0 0 1px var(--line)}\r\n.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}\r\n.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}\r\n.tbl{width:100%;border-collapse:collapse}\r\n.tbl th{font-size:12px;color:var(--muted);text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap}\r\n.tbl td{padding:11px 12px;border-bottom:1px solid #E8EDEB;vertical-align:middle}\r\n.tbl tr.click{cursor:pointer}.tbl tr.click:hover td{background:#F4F7F6}\r\n.tbl td.num,.tbl th.num{text-align:right}\r\n.nm{font-weight:700}\r\n.chip{display:inline-flex;align-items:center;height:24px;padding:0 10px;border-radius:99px;font-size:12px;font-weight:800;white-space:nowrap}\r\n.chip.good{background:var(--good-bg);color:var(--good)}.chip.ok{background:var(--ok-bg);color:var(--ok)}\r\n.chip.warn{background:var(--warn-bg);color:var(--warn)}.chip.bad{background:var(--bad-bg);color:var(--bad)}\r\n.chip.wait{background:var(--wait-bg);color:var(--wait)}\r\n.ruler{position:relative;display:inline-grid;grid-template-columns:repeat(4,1fr);gap:2px;width:104px;height:8px;vertical-align:middle}\r\n.ruler i{border-radius:2px}.ruler i:nth-child(1){background:var(--bad-seg)}.ruler i:nth-child(2){background:var(--warn-seg)}\r\n.ruler i:nth-child(3){background:var(--ok-seg)}.ruler i:nth-child(4){background:var(--good-seg)}\r\n.ruler b{position:absolute;top:-5px;bottom:-5px;width:4px;margin-left:-2px;border-radius:2px;background:var(--ink);box-shadow:0 0 0 2px var(--surface)}\r\n.ruler.off i{background:var(--line)}\r\n.mut{color:var(--muted)}.prof.good{color:var(--good)}.prof.bad{color:var(--bad)}\r\n.recent{list-style:none;margin:0;padding:6px 0}.recent li{display:flex;justify-content:space-between;gap:10px;padding:10px 18px;border-bottom:1px solid #E8EDEB}\r\n.empty{padding:36px;text-align:center;color:var(--muted);display:grid;gap:10px;justify-items:center}\r\n.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,16px);background:var(--btn);color:var(--btn-ink);padding:11px 16px;border-radius:10px;font-weight:700;opacity:0;pointer-events:none;transition:opacity .18s,transform .18s;z-index:50}\r\n.toast.on{opacity:1;transform:translate(-50%,0)}\r\n.cols{display:grid;grid-template-columns:minmax(0,640px) minmax(260px,1fr);gap:16px;align-items:start}\r\n@media(max-width:900px){.app{grid-template-columns:1fr}.side{height:auto;position:static;flex-direction:row;align-items:center}.cols,.two{grid-template-columns:1fr}}\r\n.daybar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}\r\n.daybar .long{font-weight:700;font-size:17px;margin-left:8px}\r\n.daytbl td{padding:6px 8px}\r\n.ci{width:100%;min-width:76px;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:7px;background:var(--surface);text-align:right}\r\n.ci:focus{outline:0;border-color:var(--ink)}\r\n.ci.bad{border-color:var(--bad)}\r\n.ci::placeholder{color:var(--muted);font-style:italic}\r\n.daytbl td.calc{background:#F4F7F6;text-align:right;white-space:nowrap;padding:0 10px}\r\n.savebar{position:sticky;bottom:0;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 18px;background:var(--surface);border-top:1px solid var(--line);border-radius:0 0 14px 14px}\r\n.bulkprev{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}\r\n.bulkprev span{background:#F4F7F6;border:1px solid var(--line);border-radius:99px;padding:2px 10px;font-size:12.5px}\r\n.bulkprev span.dup{border-color:var(--bad);color:var(--bad)}\r\n.warnbox{display:flex;gap:8px;align-items:flex-start;margin:0 18px 12px;font-size:12.5px;color:var(--warn);background:var(--warn-bg);border-radius:9px;padding:9px 10px}\r\n.scroll{overflow:auto;max-width:100%}\r\n.panel-h{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:14px 18px;border-bottom:1px solid #E8EDEB}\r\n.panel-h h2{margin:0;font-size:17px}\r\n.pill{height:30px;padding:0 12px;border-radius:99px;border:1px solid var(--line);background:#F4F7F6;cursor:pointer;font-weight:600;font-size:12.5px}\r\n.pill[aria-pressed=\"true\"]{background:var(--btn);color:var(--btn-ink);border-color:var(--btn)}\r\n.sheet{width:100%;border-collapse:collapse;min-width:980px}\r\n.sheet th{font-size:12px;color:var(--muted);text-align:right;padding:10px 10px;border-bottom:1px solid var(--line);white-space:nowrap}\r\n.sheet th.l,.sheet td.dt{text-align:left}\r\n.sheet td{padding:6px 8px;border-bottom:1px solid #E8EDEB;vertical-align:middle}\r\n.sheet td.calc{background:#F4F7F6;text-align:right;white-space:nowrap;padding:0 10px;font-variant-numeric:tabular-nums}\r\n.sheet td.calc.nil{color:var(--muted);font-style:italic}\r\n.sheet tfoot td{position:sticky;bottom:0;background:var(--surface);border-top:2px solid var(--ink);font-weight:800;text-align:right;white-space:nowrap;padding:12px 10px}\r\n.sheet tfoot td.dt{text-align:left}\r\n.sheet td.dt{white-space:nowrap;font-weight:700}\r\n.sheet .dia1{display:inline-block;margin-left:6px;font-size:11px;font-weight:800;color:var(--ok);background:var(--ok-bg);border-radius:99px;padding:1px 8px}\r\n.foot-note{padding:12px 18px;color:var(--muted);font-size:12.5px}\r\n.d-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}\r\n.addday{display:flex;gap:8px;align-items:center;margin-left:auto}\r\n.in.sm{height:34px;width:auto}\r\n.btn.sm{height:32px;padding:0 10px;font-size:13px}\r\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:16px}\r\n.kpi{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:12px 14px}\r\n.kpi .lbl{font-size:12px;color:var(--muted);font-weight:700}\r\n.kpi .big{font-size:20px;font-weight:800;font-variant-numeric:tabular-nums}\r\n.kpi .big.good{color:var(--good)}.kpi .big.bad{color:var(--bad)}\r\n.kpi .sub2{font-size:12px;color:var(--muted)}\r\n.dl{font-size:12px;font-weight:800}.dl.g{color:var(--good)}.dl.b{color:var(--bad)}.dl.n{color:var(--muted)}\r\n.chart{width:100%;height:220px;display:block}\r\n.dd{position:relative}\r\n.dd-menu{display:none;position:absolute;top:42px;left:0;z-index:20;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:8px;min-width:220px;box-shadow:0 8px 24px rgba(0,0,0,.12)}\r\n.dd.open .dd-menu{display:block}\r\n.dd-item{display:block;width:100%;text-align:left;border:0;background:transparent;padding:8px 10px;border-radius:8px;cursor:pointer}\r\n.dd-item:hover{background:#F4F7F6}.dd-item.on{font-weight:800;background:#F4F7F6}\r\n.dd-list{max-height:220px;overflow:auto;display:grid;gap:2px;margin:6px 0}\r\n.dd-opt{display:flex;gap:8px;align-items:center;padding:6px 8px;border-radius:8px;font-size:13px}\r\n.dd-opt small{color:var(--muted);margin-left:auto}\r\n.lnk{border:0;background:transparent;color:var(--ok);font-weight:700;cursor:pointer}\r\nth[data-sort]{cursor:pointer;user-select:none}.ar{margin-left:4px}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"app\">\r\n  <aside class=\"side\">\r\n    <div class=\"brand\">Gestor de Tráfego</div>\r\n    <nav class=\"nav\" aria-label=\"Principal\">\r\n      <a href=\"#/dashboard\" data-nav=\"dashboard\">Dashboard</a>\r\n      <a href=\"#/criativos\" data-nav=\"criativos\">Criativos</a>\r\n      <a href=\"#/cadastro\" data-nav=\"cadastro\">Cadastro</a>\r\n      <a href=\"#/lancamento\" data-nav=\"lancamento\">Lançamento</a>\r\n      <a href=\"#/config\" data-nav=\"config\">Config</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\"><div class=\"wrap\" id=\"view\"></div></main>\r\n</div>\r\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\r\n<script type=\"module\">\r\nimport * as Calc from \"/shared/calc.js\";\r\n\r\nconst $ = (s, r = document) => r.querySelector(s);\r\nconst $$ = (s, r = document) => Array.from(r.querySelectorAll(s));\r\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\r\nconst view = () => $(\"#view\");\r\nconst toast = (m) => { const t = $(\"#toast\"); t.textContent = m; t.classList.add(\"on\"); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove(\"on\"), 2600); };\r\nconst fDate = (s) => { const [y, m, d] = String(s).split(\"-\"); return `${d}/${m}/${y.slice(2)}`; };\r\nconst todayLocal = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,\"0\")}-${String(d.getDate()).padStart(2,\"0\")}`; };\r\n// Usa o módulo único de cálculo servido pelo servidor (ao-vivo + formato BR).\r\nconst fBRL = (cents) => Calc.formatBRL(cents);\r\n\r\nconst FORMAT = { video: \"Vídeo\", image: \"Imagem\", carousel: \"Carrossel\" };\r\nconst STATUS = { ativo: \"Ativo\", escalando: \"Escalando\", pausado: \"Pausado\", encerrado: \"Encerrado\" };\r\n\r\nfunction chipFor(h) {\r\n  const map = { \"Saudável\": \"ok\", \"Atenção\": \"warn\", \"Escalando\": \"good\", \"Pausado\": \"bad\", \"Encerrado\": \"bad\", \"Sem dados\": \"wait\" };\r\n  return `<span class=\"chip ${map[h.statusDisplay] ?? \"wait\"}\">${esc(h.statusDisplay)}</span>`;\r\n}\r\nfunction rulerFor(h) {\r\n  const pos = { vermelho: 12, amarelo: 37, azul: 62, verde: 87 };\r\n  if (h.ruler === \"cinza\") return `<span class=\"ruler off\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span>`;\r\n  return `<span class=\"ruler\" role=\"img\" aria-label=\"Saúde ${esc(h.statusDisplay)}\"><i></i><i></i><i></i><i></i><b style=\"left:${pos[h.ruler] ?? 62}%\"></b></span>`;\r\n}\r\nconst profitClass = (cents) => cents == null ? \"\" : cents >= 0 ? \"good\" : \"bad\";\r\nasync function api(path, opts) {\r\n  const res = await fetch(path, opts);\r\n  const body = await res.json().catch(() => ({}));\r\n  if (!res.ok) { const e = new Error(body.error || \"erro\"); e.status = res.status; e.body = body; throw e; }\r\n  return body;\r\n}\r\n\r\n// ---------- Biblioteca (T5: busca + status + ordenação lucro/ROAS/custo/vendas) ----------\r\nconst L = { q: \"\", status: \"all\", sort: \"recent\" };\r\nconst fRoas = (n) => Calc.formatRoas(n);\r\nasync function pageLibrary() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Criativos</h1><p class=\"sub\" id=\"lib-sub\">Biblioteca — busque, filtre e compare</p></div><a class=\"btn\" href=\"#/cadastro\">+ Cadastrar criativo</a></div>\r\n  <div class=\"fb\">\r\n    <label class=\"ctl search\"><input id=\"lib-q\" placeholder=\"Buscar por nome ou produto\" value=\"${esc(L.q)}\" aria-label=\"Buscar criativo\"></label>\r\n    <label class=\"ctl\">Status <select id=\"lib-status\"><option value=\"all\">Todos</option>${Object.entries(STATUS).map(([k,v]) => `<option value=\"${k}\">${v}</option>`).join(\"\")}</select></label>\r\n    <label class=\"ctl\">Ordenar <select id=\"lib-sort\"><option value=\"recent\">Mais recentes</option><option value=\"name\">Nome A–Z</option><option value=\"profit\">Maior lucro</option><option value=\"roas\">Maior ROAS-equiv.</option><option value=\"cost\">Maior custo</option><option value=\"sales\">Mais vendas</option></select></label>\r\n  </div>\r\n  <section class=\"panel\"><div class=\"panel-b\" id=\"lib-body\">Carregando…</div></section>`;\r\n  $(\"#lib-status\").value = L.status; $(\"#lib-sort\").value = L.sort;\r\n  $(\"#lib-q\").addEventListener(\"input\", (e) => { L.q = e.target.value; libBody(); });\r\n  $(\"#lib-status\").addEventListener(\"change\", (e) => { L.status = e.target.value; libBody(); });\r\n  $(\"#lib-sort\").addEventListener(\"change\", (e) => { L.sort = e.target.value; libBody(); });\r\n  $(\"#lib-body\").addEventListener(\"click\", (e) => { const tr = e.target.closest(\"tr[data-id]\"); if (tr) location.hash = \"#/criativo/\" + tr.dataset.id; });\r\n  await libBody();\r\n}\r\nasync function libBody() {\r\n  const box = $(\"#lib-body\");\r\n  try {\r\n    const qs = new URLSearchParams();\r\n    if (L.q.trim()) qs.set(\"q\", L.q.trim());\r\n    if (L.status !== \"all\") qs.set(\"status\", L.status);\r\n    // Ordenação no servidor (contrato ?sort=profit|roas|cost|sales|name|recent).\r\n    if (L.sort && L.sort !== \"recent\") qs.set(\"sort\", L.sort);\r\n    const { data } = await api(\"/api/creatives?\" + qs.toString());\r\n    const rows = [...data];\r\n    $(\"#lib-sub\").textContent = `${rows.length} criativo(s) na biblioteca`;\r\n    if (!rows.length) { box.innerHTML = `<div class=\"empty\"><strong>Nenhum criativo encontrado</strong><span>Tente outra busca ou cadastre um novo.</span><a class=\"btn\" href=\"#/cadastro\">Cadastrar criativo</a></div>`; return; }\r\n    box.innerHTML = `<div style=\"overflow:auto\"><table class=\"tbl\"><thead><tr><th>Criativo</th><th>Status</th><th class=\"num\">Custo</th><th class=\"num\">Vendas</th><th class=\"num\">ROAS-equiv.</th><th class=\"num\">Lucro</th><th>Saúde do dia</th><th>Motivo</th></tr></thead><tbody>${rows.map((c) => {\r\n      const pc = profitClass(c.totals.profit_cents);\r\n      const roas = c.totals.roas_equivalente;\r\n      return `<tr class=\"click\" data-id=\"${c.id}\"><td><div class=\"nm\">${esc(c.name)}</div><div class=\"sub\">${esc(c.product || \"—\")} · ${FORMAT[c.format] ?? c.format} · ${fDate(c.start_date)}</div></td><td>${chipFor(c.health)}</td><td class=\"num\">${fBRL(c.totals.cost_cents)}</td><td class=\"num\">${c.totals.sales}</td><td class=\"num\">${roas == null ? \"—\" : fRoas(roas)}</td><td class=\"num prof ${pc}\">${c.totals.profit_cents == null ? (c.totals.has_pending ? \"pendente\" : \"—\") : fBRL(c.totals.profit_cents)}</td><td>${rulerFor(c.health)}</td><td class=\"mut\">${esc(c.health.motivo ?? \"—\")}</td></tr>`;\r\n    }).join(\"\")}</tbody></table></div><div class=\"foot-note\">ROAS-equiv. = faturamento ÷ custo c/ imposto (só comparação — a cor vem do Sinal). Lucro “pendente” = vendeu e o faturamento ainda não foi lançado.</div>`;\r\n  } catch { box.innerHTML = `<div class=\"empty\"><strong>Não foi possível carregar</strong></div>`; }\r\n}\r\n\r\n// ---------- Cadastro (T2 único + T3 em lote) ----------\r\n// produto/formato/data mantidos após cada cadastro para encadear o próximo.\r\nconst R = { mode: \"single\", name: \"\", bulk: \"\", product: \"\", format: \"video\", start: todayLocal(), status: \"ativo\", url: \"\", notes: \"\" };\r\nconst bulkNames = () => R.bulk.split(\"\\n\").map((s) => s.trim()).filter(Boolean);\r\nasync function pageRegister() {\r\n  let products = [];\r\n  let existing = [];\r\n  try { const { data } = await api(\"/api/creatives\"); products = [...new Set(data.map((c) => c.product).filter(Boolean))].sort((a,b)=>a.localeCompare(b,\"pt-BR\")); existing = data.map((c) => ({ name: c.name, status: c.status })); } catch {}\r\n  const bulk = R.mode === \"bulk\";\r\n  const isFuture = R.start > todayLocal();\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Cadastro</h1><p class=\"sub\">Registre os criativos novos. Os números do dia entram depois, no lançamento.</p></div></div>\r\n  <div class=\"cols\">\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <div class=\"seg\" role=\"group\" aria-label=\"Modo de cadastro\"><button type=\"button\" data-mode=\"single\" aria-pressed=\"${!bulk}\">Um criativo</button><button type=\"button\" data-mode=\"bulk\" aria-pressed=\"${bulk}\">Vários de uma vez</button></div>\r\n    <div style=\"height:14px\"></div>\r\n    ${bulk\r\n      ? `<div class=\"fld\"><label for=\"r-bulk\">Nomes dos criativos (um por linha)</label><textarea class=\"in\" id=\"r-bulk\" rows=\"6\" placeholder=\"Depoimento cozinha 03&#10;UGC achadinho 04\">${esc(R.bulk)}</textarea><div class=\"bulkprev\" id=\"r-prev\" aria-live=\"polite\"></div><div class=\"err-msg\" id=\"r-err\" hidden></div></div>`\r\n      : `<div class=\"fld\"><label for=\"r-name\">Nome do criativo</label><input class=\"in\" id=\"r-name\" value=\"${esc(R.name)}\" placeholder=\"Ex.: Depoimento cozinha 03\" autocomplete=\"off\"><div class=\"err-msg\" id=\"r-err\" hidden></div></div>`}\r\n    <div class=\"fld\"><label for=\"r-product\">Produto ou oferta</label><input class=\"in\" id=\"r-product\" list=\"r-products\" value=\"${esc(R.product)}\" placeholder=\"Ex.: Mini processador\" autocomplete=\"off\"><datalist id=\"r-products\">${products.map((p)=>`<option value=\"${esc(p)}\">`).join(\"\")}</datalist><span class=\"hint\">Mantido após cadastrar para encadear o próximo.</span></div>\r\n    <div class=\"fld\"><span class=\"l\" style=\"font-weight:700\">Formato</span><div class=\"seg\" role=\"group\" aria-label=\"Formato\">${Object.entries(FORMAT).map(([k,v])=>`<button type=\"button\" data-format=\"${k}\" aria-pressed=\"${R.format===k}\">${v}</button>`).join(\"\")}</div></div>\r\n    <div class=\"two\">\r\n      <div class=\"fld\"><label for=\"r-start\">Data de início</label><input type=\"date\" class=\"in\" id=\"r-start\" value=\"${esc(R.start)}\"><span class=\"hint\">Mantida após cadastrar.</span></div>\r\n      <div class=\"fld\"><label for=\"r-status\">Status inicial</label><select class=\"in\" id=\"r-status\">${Object.entries(STATUS).map(([k,v])=>`<option value=\"${k}\">${v}</option>`).join(\"\")}</select></div>\r\n    </div>\r\n    ${isFuture ? `<p class=\"hint\" id=\"r-pre\">Pré-cadastro: começa em ${fDate(R.start)} — não conta Dia 1 nem dispara Sinal até ter movimento.</p>` : ``}\r\n    ${bulk ? `` : `\r\n    <div class=\"fld\"><label for=\"r-url\">Link do Criativo (opcional)</label><input class=\"in\" id=\"r-url\" type=\"url\" value=\"${esc(R.url)}\" placeholder=\"Pasta do Drive ou link do Criativo\"></div>\r\n    <div class=\"fld\"><label for=\"r-notes\">Observações (opcional)</label><textarea class=\"in\" id=\"r-notes\" placeholder=\"Gancho, ângulo, público…\">${esc(R.notes)}</textarea></div>`}\r\n    <div class=\"actions\"><button class=\"btn\" id=\"r-save\" type=\"button\"><span id=\"r-save-l\">Cadastrar</span></button><button class=\"btn ghost\" id=\"r-save-go\" type=\"button\">Cadastrar e lançar dados</button></div>\r\n  </div></section>\r\n  <section class=\"panel\"><div class=\"panel-b\"><strong>Últimos cadastrados</strong></div><ul class=\"recent\" id=\"r-recent\"><li class=\"mut\">Carregando…</li></ul></section>\r\n  </div>`;\r\n  $(\"#r-status\").value = R.status;\r\n  const errEl = () => $(\"#r-err\");\r\n  const showErr = (m, sel) => { const e = errEl(); e.textContent = m; e.hidden = false; const i = sel ? $(sel) : null; if (i) { i.classList.add(\"err\"); i.focus(); } };\r\n  const clearErr = () => { const e = errEl(); if (e) e.hidden = true; $$(\".in.err\").forEach((i)=>i.classList.remove(\"err\")); };\r\n  const paintPreview = () => {\r\n    const box = $(\"#r-prev\");\r\n    if (!box) { const l = $(\"#r-save-l\"); if (l) l.textContent = \"Cadastrar\"; return; }\r\n    const names = bulkNames();\r\n    const taken = new Set(existing.filter((c) => c.status !== \"encerrado\").map((c) => String(c.name).toLowerCase()));\r\n    const seen = new Set();\r\n    box.innerHTML = names.map((n) => {\r\n      const k = n.toLowerCase();\r\n      const dup = taken.has(k) || seen.has(k);\r\n      seen.add(k);\r\n      return `<span class=\"${dup ? \"dup\" : \"\"}\">${esc(n)}</span>`;\r\n    }).join(\"\");\r\n    $(\"#r-save-l\").textContent = names.length > 1 ? `Cadastrar ${names.length} criativos` : \"Cadastrar\";\r\n  };\r\n  $$(\"[data-mode]\").forEach((b) => b.addEventListener(\"click\", () => { R.mode = b.dataset.mode; pageRegister(); }));\r\n  const nameInput = $(\"#r-name\");\r\n  if (nameInput) nameInput.addEventListener(\"input\", (e) => { R.name = e.target.value; clearErr(); });\r\n  const bulkInput = $(\"#r-bulk\");\r\n  if (bulkInput) bulkInput.addEventListener(\"input\", (e) => { R.bulk = e.target.value; clearErr(); paintPreview(); });\r\n  $(\"#r-product\").addEventListener(\"input\", (e) => { R.product = e.target.value; });\r\n  $(\"#r-start\").addEventListener(\"change\", (e) => { R.start = e.target.value || todayLocal(); pageRegister(); });\r\n  $(\"#r-status\").addEventListener(\"change\", (e) => { R.status = e.target.value; });\r\n  const urlInput = $(\"#r-url\");\r\n  if (urlInput) urlInput.addEventListener(\"input\", (e) => { R.url = e.target.value; });\r\n  const notesInput = $(\"#r-notes\");\r\n  if (notesInput) notesInput.addEventListener(\"input\", (e) => { R.notes = e.target.value; });\r\n  $$(\"[data-format]\").forEach((b) => b.addEventListener(\"click\", () => { R.format = b.dataset.format; $$(\"[data-format]\").forEach((x)=>x.setAttribute(\"aria-pressed\", x===b)); }));\r\n  $(\"#r-save\").addEventListener(\"click\", () => submitRegister(false, showErr));\r\n  $(\"#r-save-go\").addEventListener(\"click\", () => submitRegister(true, showErr));\r\n  paintPreview();\r\n  await paintRecent();\r\n}\r\nasync function paintRecent() {\r\n  try {\r\n    const { data } = await api(\"/api/creatives\");\r\n    const last = [...data].sort((a,b)=>b.id-a.id).slice(0,6);\r\n    $(\"#r-recent\").innerHTML = last.length ? last.map((c)=>`<li><div><a href=\"#/criativo/${c.id}\">${esc(c.name)}</a><div class=\"sub\">${esc(c.product||\"—\")} · ${FORMAT[c.format]} · ${fDate(c.start_date)}</div></div>${chipFor(c.health)}</li>`).join(\"\") : `<li class=\"mut\">Nenhum criativo ainda.</li>`;\r\n  } catch { const el = $(\"#r-recent\"); if (el) el.innerHTML = `<li class=\"mut\">—</li>`; }\r\n}\r\nasync function submitRegister(goDaily, err) {\r\n  if (R.mode === \"bulk\") {\r\n    const names = bulkNames();\r\n    if (!names.length) { err(\"Digite pelo menos um nome, um por linha.\", \"#r-bulk\"); return; }\r\n    try {\r\n      const { data } = await api(\"/api/creatives/bulk\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ names, product: R.product.trim(), format: R.format, start_date: R.start, status: R.status }) });\r\n      // Mantém produto/formato/data para encadear; limpa só a lista.\r\n      R.bulk = \"\";\r\n      toast(data.length === 1 ? `Criativo cadastrado: ${data[0].name}` : `${data.length} criativos cadastrados`);\r\n      if (goDaily) { location.hash = \"#/lancamento\"; } else { pageRegister(); const f = $(\"#r-bulk\"); if (f) f.focus(); }\r\n    } catch (e) {\r\n      const warns = e.body?.warnings ?? [];\r\n      if (e.body?.error === \"nome_duplicado\") err(warns[0] || \"Há nomes repetidos ou já cadastrados (em vermelho).\", \"#r-bulk\");\r\n      else err(\"Não foi possível cadastrar. Confira os campos.\", \"#r-bulk\");\r\n    }\r\n    return;\r\n  }\r\n  const payload = { name: R.name.trim(), product: R.product.trim(), format: R.format, start_date: R.start, status: R.status, url: R.url.trim(), notes: R.notes };\r\n  if (!payload.name) { err(\"Informe o nome do criativo.\", \"#r-name\"); return; }\r\n  try {\r\n    const { data } = await api(\"/api/creatives\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify(payload) });\r\n    // Mantém produto/formato/data para encadear; limpa só nome/link/observações.\r\n    R.name = \"\"; R.url = \"\"; R.notes = \"\";\r\n    toast(`Criativo cadastrado: ${data.name}`);\r\n    if (goDaily) { location.hash = \"#/lancamento\"; } else { pageRegister(); const f = $(\"#r-name\"); if (f) f.focus(); }\r\n  } catch (e) {\r\n    const warns = e.body?.warnings ?? [];\r\n    if (e.body?.error === \"nome_duplicado\") err(warns[0] || \"Já existe um criativo com esse nome.\", \"#r-name\");\r\n    else err(\"Não foi possível cadastrar. Confira os campos.\", \"#r-name\");\r\n  }\r\n}\r\n\r\n// ---------- Detalhe réplica-da-planilha (T4) ----------\r\n// Colunas digitáveis (brancas): Investimento, Vendas, Faturamento, Cliques Meta/Shopee.\r\n// Colunas calculadas (cinza, via Calc): Custo, Lucro, CPCs. TOTAL fixo no rodapé = agg().\r\n// Filtro por mês, adicionar dia (upsert por data), ciclo de vida + régua/Status/Motivo.\r\nconst DT = { id: null, month: \"all\", creative: null, entries: [], months: [], dia1: null, health: null };\r\nconst monthLabel = (m) => { const [y, mo] = m.split(\"-\"); return `${mo}/${y.slice(2)}`; };\r\nasync function pageDetail(id) {\r\n  DT.id = id; DT.month = \"all\"; DT.creative = null; DT.entries = [];\r\n  view().innerHTML = `<div class=\"panel-b mut\">Carregando…</div>`;\r\n  try {\r\n    await loadDetail();\r\n  } catch { location.hash = \"#/criativos\"; }\r\n}\r\nasync function loadDetail() {\r\n  const id = DT.id;\r\n  const qs = DT.month !== \"all\" ? \"?month=\" + encodeURIComponent(DT.month) : \"\";\r\n  const [{ data: c }, det] = await Promise.all([\r\n    api(\"/api/creatives/\" + id),\r\n    api(\"/api/creatives/\" + id + \"/entries\" + qs),\r\n  ]);\r\n  DT.creative = det.data.creative;\r\n  DT.entries = det.data.entries;\r\n  DT.months = det.data.months;\r\n  DT.dia1 = det.data.dia1;\r\n  DT.health = det.data.health;\r\n  renderDetail(c.data, det);\r\n}\r\nfunction renderDetail(c, det) {\r\n  const h = det.data.health;\r\n  const pc = profitClass(det.data.totals.profit_cents);\r\n  const encerrado = DT.creative.status === \"encerrado\";\r\n  const st = DT.creative.status;\r\n  const actions =\r\n    st === \"ativo\" ? `<button class=\"btn ghost sm\" data-act=\"escalando\" type=\"button\">Escalar</button><button class=\"btn ghost sm\" data-act=\"pausado\" type=\"button\">Pausar</button><button class=\"btn ghost sm\" data-act=\"encerrado\" type=\"button\">Encerrar</button>`\r\n    : st === \"escalando\" ? `<button class=\"btn ghost sm\" data-act=\"ativo\" type=\"button\">Desmarcar escala</button><button class=\"btn ghost sm\" data-act=\"pausado\" type=\"button\">Pausar</button><button class=\"btn ghost sm\" data-act=\"encerrado\" type=\"button\">Encerrar</button>`\r\n    : st === \"pausado\" ? `<button class=\"btn sm\" data-act=\"ativo\" type=\"button\">Reabrir</button><button class=\"btn ghost sm\" data-act=\"encerrado\" type=\"button\">Encerrar</button>`\r\n    : `<button class=\"btn sm\" data-act=\"ativo\" type=\"button\">Reabrir</button>`;\r\n  const t = det.data.totals;\r\n  const profitLabel = t.profit_cents == null ? (t.has_pending ? \"pendente\" : \"—\") : fBRL(t.profit_cents);\r\n  view().innerHTML = `\r\n  <a href=\"#/criativos\" style=\"color:var(--muted);text-decoration:none\">← Criativos</a>\r\n  <div class=\"ph\"><div><h1>${esc(DT.creative.name)}</h1><p class=\"sub\">${esc(DT.creative.product || \"—\")} · ${FORMAT[DT.creative.format]} · início em ${fDate(DT.creative.start_date)}</p></div><div class=\"d-actions\">${chipFor(h)}${actions}</div></div>\r\n  <section class=\"panel\"><div class=\"panel-b\" style=\"display:flex;gap:24px;flex-wrap:wrap;align-items:center\">${rulerFor(h)}<span><strong class=\"prof ${pc}\">${esc(profitLabel)}</strong> <span class=\"mut\">lucro · ${fBRL(t.investment_cents)} investidos · ${t.sales} vendas</span></span><span class=\"mut\">${esc(h.motivo ?? (h.dia1 ? \"—\" : \"Pré-cadastro: sem Dia 1, sem Sinal até ter movimento.\"))}</span></div>\r\n  ${det.warnings?.length ? `<div class=\"warnbox\">${esc(det.warnings.join(\" \"))}</div>` : ``}</section>\r\n  <section class=\"panel\">\r\n    <div class=\"panel-h\"><h2>Lançamentos diários</h2><div id=\"d-months\" style=\"display:flex;gap:6px;flex-wrap:wrap\">${[[\"all\", \"Tudo\"], ...DT.months.map((m) => [m, monthLabel(m)])].map(([k, l]) => `<button type=\"button\" class=\"pill\" data-m=\"${k}\" aria-pressed=\"${DT.month === k}\">${l}</button>`).join(\"\")}</div>\r\n    <div class=\"addday\"><input type=\"date\" class=\"in sm\" id=\"add-date\" aria-label=\"Data do novo lançamento\" ${encerrado ? \"disabled\" : \"\"}><button class=\"btn sm\" id=\"add-btn\" type=\"button\" ${encerrado ? \"disabled\" : \"\"}>+ Adicionar dia</button></div></div>\r\n    <div class=\"scroll\" id=\"sheetbox\"></div>\r\n    <div class=\"foot-note\">Colunas em cinza são calculadas (Custo = investimento × (1 + imposto) · Lucro = faturamento − custo · CPC = investimento ÷ cliques). Deixe o faturamento vazio até a comissão ser confirmada: o dia fica pendente, fora do lucro. Valores em R$. ${encerrado ? \"Encerrado: histórico, sem lançamentos — reabra para lançar.\" : \"\"}</div>\r\n  </section>`;\r\n  $(\"#d-months\").addEventListener(\"click\", (e) => {\r\n    const b = e.target.closest(\"[data-m]\");\r\n    if (!b) return;\r\n    DT.month = b.dataset.m;\r\n    loadDetail();\r\n  });\r\n  view().querySelector(\".d-actions\").addEventListener(\"click\", async (e) => {\r\n    const b = e.target.closest(\"[data-act]\");\r\n    if (!b) return;\r\n    try {\r\n      await api(\"/api/creatives/\" + DT.id, { method: \"PATCH\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ status: b.dataset.act }) });\r\n      toast(b.dataset.act === \"escalando\" ? \"Marcado como Escalando\" : b.dataset.act === \"ativo\" ? (st === \"encerrado\" || st === \"pausado\" ? \"Criativo reaberto\" : \"Escala desmarcada\") : b.dataset.act === \"pausado\" ? \"Criativo pausado — ainda recebe vendas (cookie)\" : \"Criativo encerrado — fica no histórico\");\r\n      await loadDetail();\r\n    } catch (err) {\r\n      toast(err.body?.error === \"escalando_so_do_ativo\" ? \"Só criativos Ativos podem ser Escalando.\" : \"Não foi possível atualizar o status.\");\r\n    }\r\n  });\r\n  const last = DT.entries.length ? DT.entries[0].date : DT.creative.start_date;\r\n  const addInput = $(\"#add-date\");\r\n  if (addInput && !encerrado) {\r\n    addInput.value = last;\r\n    addInput.max = todayLocal();\r\n    $(\"#add-btn\").addEventListener(\"click\", async () => {\r\n      const d = addInput.value;\r\n      if (!d) return;\r\n      if (DT.entries.some((e) => e.date === d)) {\r\n        const tr = view().querySelector(`tr[data-date=\"${d}\"]`);\r\n        if (tr) { tr.scrollIntoView({ block: \"nearest\" }); const i = tr.querySelector(\"input\"); if (i) i.focus(); }\r\n        return;\r\n      }\r\n      try {\r\n        await api(`/api/creatives/${DT.id}/entries/${d}`, { method: \"PUT\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ investment_cents: 0, sales: 0, revenue_cents: null, clicks_meta: 0, clicks_shopee: 0 }) });\r\n        if (DT.month !== \"all\") DT.month = d.slice(0, 7);\r\n        toast(`Dia ${fDate(d)} adicionado`);\r\n        await loadDetail();\r\n      } catch (err) {\r\n        toast(err.body?.error === \"encerrado_sem_lancamento\" ? \"Criativo encerrado não recebe lançamentos.\" : \"Não foi possível adicionar o dia.\");\r\n      }\r\n    });\r\n  }\r\n  renderSheet();\r\n  const box = $(\"#sheetbox\");\r\n  box.addEventListener(\"input\", (ev) => {\r\n    const inp = ev.target.closest(\"input[data-f]\");\r\n    if (!inp) return;\r\n    paintDetailRow(inp.closest(\"tr\"));\r\n    paintDetailTotals();\r\n  });\r\n  box.addEventListener(\"keydown\", (ev) => {\r\n    if (ev.key !== \"Enter\" || !ev.target.matches(\"input[data-f]\")) return;\r\n    ev.preventDefault();\r\n    ev.target.blur();\r\n  });\r\n  box.addEventListener(\"focusout\", async (ev) => {\r\n    const inp = ev.target.closest(\"input[data-f]\");\r\n    if (!inp) return;\r\n    const tr = inp.closest(\"tr\");\r\n    if (inp.classList.contains(\"bad\")) return;\r\n    await saveDetailRow(tr);\r\n  });\r\n}\r\nfunction detailEntryFromRow(tr) {\r\n  const tax = Number(tr.dataset.tax || 0.1386);\r\n  const date = tr.dataset.date;\r\n  const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\r\n  const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\r\n  const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\r\n  const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\r\n  const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\r\n  return { tax, date, inv, rev, sales, clM, clS };\r\n}\r\nfunction paintDetailRow(tr) {\r\n  const { tax, date, inv, rev, sales, clM, clS } = detailEntryFromRow(tr);\r\n  const bad =\r\n    [inv, sales, clM, clS].some((v) => typeof v === \"number\" && Number.isNaN(v)) ||\r\n    (rev != null && Number.isNaN(rev));\r\n  [\"invest\", \"sales\", \"rev\", \"clM\", \"clS\"].forEach((f) => $('[data-f=\"' + f + '\"]', tr).classList.remove(\"bad\"));\r\n  if (bad) return;\r\n  const invC = inv == null ? 0 : inv;\r\n  const salesN = sales == null ? 0 : sales;\r\n  const clMN = clM == null ? 0 : clM;\r\n  const clSN = clS == null ? 0 : clS;\r\n  const row = Calc.calcRow({ date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax });\r\n  $('[data-c=\"cost\"]', tr).textContent = Calc.formatBRL(row.cost_cents);\r\n  const pEl = $('[data-c=\"profit\"]', tr);\r\n  pEl.textContent = row.is_pending ? \"pendente\" : Calc.formatBRL(row.profit_cents);\r\n  pEl.className = \"calc\" + (row.profit_cents == null || row.is_pending ? \" nil\" : row.profit_cents >= 0 ? \" prof good\" : \" prof bad\");\r\n  $('[data-c=\"cpcM\"]', tr).textContent = Calc.formatCPC(row.cpc_meta_cents);\r\n  $('[data-c=\"cpcS\"]', tr).textContent = Calc.formatCPC(row.cpc_shopee_cents);\r\n  const hEl = $('[data-c=\"health\"]', tr);\r\n  const dayForSignal = { date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax };\r\n  // Módulo único: dia sem movimento nunca tem sinal (igual ao servidor).\r\n  if (!Calc.hasMovement(dayForSignal)) { hEl.textContent = \"—\"; return; }\r\n  try {\r\n    // Ao-vivo: data anterior ao Dia 1 salvo vira o novo Dia 1 após salvar (<=);\r\n    // sem Dia 1 salvo, o primeiro dia com movimento é o Dia 1.\r\n    const isDia1 = !DT.dia1 || date <= DT.dia1;\r\n    const sig = Calc.evaluateDay(dayForSignal, isDia1);\r\n    hEl.textContent = sig.saude === \"atencao\" ? `Atenção · ${sig.motivo ?? \"\"}` : (sig.motivo ?? \"Saudável\");\r\n  } catch { hEl.textContent = \"—\"; }\r\n}\r\nfunction paintDetailTotals() {\r\n  const rows = $$(\"#sheetbox tr[data-date]\");\r\n  const days = [];\r\n  for (const tr of rows) {\r\n    const { tax, date, inv, rev, sales, clM, clS } = detailEntryFromRow(tr);\r\n    if ([inv, sales, clM, clS].some((v) => typeof v === \"number\" && Number.isNaN(v))) continue;\r\n    days.push({ date, investment_cents: inv ?? 0, sales: sales ?? 0, revenue_cents: rev, clicks_meta: clM ?? 0, clicks_shopee: clS ?? 0, tax_rate: tax });\r\n  }\r\n  const a = Calc.agg(days);\r\n  const set = (k, txt, cls) => { const td = view().querySelector(`[data-t=\"${k}\"]`); if (td) { td.textContent = txt; if (cls) td.className = cls; } };\r\n  set(\"invest\", Calc.formatBRL(a.investment_cents));\r\n  set(\"cost\", Calc.formatBRL(a.cost_cents));\r\n  set(\"sales\", String(a.sales));\r\n  set(\"rev\", a.costClosed_cents > 0 || a.revenue_cents > 0 ? Calc.formatBRL(a.revenue_cents) : \"—\");\r\n  set(\"profit\", a.profit_cents == null ? (a.has_pending ? \"pendente\" : \"—\") : Calc.formatBRL(a.profit_cents));\r\n  set(\"clM\", String(a.clicks_meta));\r\n  set(\"clS\", String(a.clicks_shopee));\r\n  set(\"cpcM\", Calc.formatCPC(a.cpc_meta_cents));\r\n  set(\"cpcS\", Calc.formatCPC(a.cpc_shopee_cents));\r\n}\r\nfunction renderSheet() {\r\n  const box = $(\"#sheetbox\");\r\n  const encerrado = DT.creative.status === \"encerrado\";\r\n  if (!DT.entries.length) {\r\n    box.innerHTML = `<div class=\"empty\"><strong>Nenhum lançamento${DT.month !== \"all\" ? \" neste mês\" : \" ainda\"}</strong><span>${encerrado ? \"Criativo encerrado: histórico, sem lançamentos.\" : \"Adicione o primeiro dia acima ou lance pelo Lançamento diário.\"}</span></div>`;\r\n    return;\r\n  }\r\n  box.innerHTML = `<table class=\"sheet\"><thead><tr><th class=\"l\">Data</th><th>Investimento</th><th>Custo c/ imposto</th><th>Vendas</th><th>Faturamento</th><th>Lucro</th><th>Cliques Meta</th><th>Cliques Shopee</th><th>CPC Meta</th><th>CPC Shopee</th><th class=\"l\">Saúde do dia</th></tr></thead><tbody>${DT.entries.map((e) => {\r\n    const dis = encerrado ? \"disabled\" : \"\";\r\n    return `<tr data-date=\"${e.date}\" data-tax=\"${e.tax_rate}\"><td class=\"dt\">${fDate(e.date)}${e.is_dia1 ? `<span class=\"dia1\">Dia 1</span>` : ``}</td>`\r\n      + `<td><input class=\"ci\" data-f=\"invest\" inputmode=\"decimal\" value=\"${esc(e.investment_cents ? fmtInputCents(e.investment_cents) : \"\")}\" placeholder=\"0,00\" ${dis}></td>`\r\n      + `<td class=\"calc\" data-c=\"cost\">—</td>`\r\n      + `<td><input class=\"ci\" data-f=\"sales\" inputmode=\"numeric\" value=\"${esc(e.sales ? String(e.sales) : \"\")}\" placeholder=\"0\" ${dis}></td>`\r\n      + `<td><input class=\"ci\" data-f=\"rev\" inputmode=\"decimal\" value=\"${esc(e.revenue_cents != null ? fmtInputCents(e.revenue_cents) : \"\")}\" placeholder=\"pendente\" ${dis}></td>`\r\n      + `<td class=\"calc\" data-c=\"profit\">—</td>`\r\n      + `<td><input class=\"ci\" data-f=\"clM\" inputmode=\"numeric\" value=\"${esc(e.clicks_meta ? String(e.clicks_meta) : \"\")}\" placeholder=\"0\" ${dis}></td>`\r\n      + `<td><input class=\"ci\" data-f=\"clS\" inputmode=\"numeric\" value=\"${esc(e.clicks_shopee ? String(e.clicks_shopee) : \"\")}\" placeholder=\"0\" ${dis}></td>`\r\n      + `<td class=\"calc\" data-c=\"cpcM\">—</td><td class=\"calc\" data-c=\"cpcS\">—</td>`\r\n      + `<td class=\"mut\" data-c=\"health\" style=\"white-space:normal;min-width:140px\">—</td></tr>`;\r\n  }).join(\"\")}</tbody><tfoot><tr><td class=\"dt\">TOTAL</td><td data-t=\"invest\"></td><td data-t=\"cost\"></td><td data-t=\"sales\"></td><td data-t=\"rev\"></td><td data-t=\"profit\"></td><td data-t=\"clM\"></td><td data-t=\"clS\"></td><td data-t=\"cpcM\"></td><td data-t=\"cpcS\"></td><td></td></tr></tfoot></table>`;\r\n  $$(\"#sheetbox tr[data-date]\").forEach(paintDetailRow);\r\n  paintDetailTotals();\r\n}\r\nasync function saveDetailRow(tr) {\r\n  const date = tr.dataset.date;\r\n  const { inv, rev, sales, clM, clS } = detailEntryFromRow(tr);\r\n  const name = DT.creative.name;\r\n  let bad = false;\r\n  const mark = (f) => { $('[data-f=\"' + f + '\"]', tr).classList.add(\"bad\"); bad = true; };\r\n  for (const [f, v] of [[\"invest\", inv], [\"sales\", sales], [\"rev\", rev], [\"clM\", clM], [\"clS\", clS]]) {\r\n    if (typeof v === \"number\" && Number.isNaN(v)) mark(f);\r\n    if (typeof v === \"number\" && v != null && v < 0) mark(f);\r\n  }\r\n  for (const [f, v] of [[\"sales\", sales], [\"clM\", clM], [\"clS\", clS]]) {\r\n    if (typeof v === \"number\" && v != null && !Number.isInteger(v)) mark(f);\r\n  }\r\n  if (bad) { toast(`Confira os números de ${name} em ${fDate(date)}.`); return; }\r\n  try {\r\n    await api(`/api/creatives/${DT.id}/entries/${date}`, { method: \"PUT\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ investment_cents: inv ?? 0, sales: sales ?? 0, revenue_cents: rev, clicks_meta: clM ?? 0, clicks_shopee: clS ?? 0 }) });\r\n    toast(`Dia ${fDate(date)} salvo`);\r\n    await loadDetail();\r\n  } catch (err) {\r\n    toast(err.body?.error === \"encerrado_sem_lancamento\" ? \"Criativo encerrado não recebe lançamentos.\" : \"Não foi possível salvar. Confira os números.\");\r\n  }\r\n}\r\n// ---------- Lançamento diário em lote (T3) ----------\r\n// Um dia, todos os Ativos numa tabela só. Tudo recalcula ao digitar via Calc.\r\nconst DY = { date: todayLocal() };\r\nconst fmtInputCents = (cents) => cents == null ? \"\" : (cents / 100).toLocaleString(\"pt-BR\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\r\nfunction pageDaily() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Lançamento diário</h1><p class=\"sub\">Lance o dia de todos os Ativos numa tabela só.</p></div><a class=\"btn ghost\" href=\"#/cadastro\">Cadastrar criativo</a></div>\r\n  <div class=\"daybar\">\r\n    <button class=\"btn ghost sm\" id=\"dy-prev\" type=\"button\" aria-label=\"Dia anterior\">←</button>\r\n    <input type=\"date\" class=\"in sm\" id=\"dy-date\" style=\"width:auto\" aria-label=\"Data do lançamento\">\r\n    <button class=\"btn ghost sm\" id=\"dy-next\" type=\"button\" aria-label=\"Próximo dia\">→</button>\r\n    <button class=\"btn ghost sm\" id=\"dy-today\" type=\"button\">Hoje</button>\r\n    <span class=\"long\" id=\"dy-long\"></span>\r\n  </div>\r\n  <section class=\"panel\"><div class=\"scroll\" id=\"dy-body\"><div class=\"panel-b mut\">Carregando…</div></div>\r\n    <div class=\"warnbox\" id=\"dy-warn\" hidden></div>\r\n    <div class=\"savebar\"><span id=\"dy-count\" class=\"mut\"></span><button class=\"btn\" id=\"dy-save\" type=\"button\">Salvar lançamentos</button></div></section>`;\r\n  const go = (d) => { if (!d || d > todayLocal()) return; DY.date = d; renderDay(); };\r\n  $(\"#dy-date\").max = todayLocal();\r\n  $(\"#dy-prev\").addEventListener(\"click\", () => {\r\n    const [y, m, d] = DY.date.split(\"-\").map(Number);\r\n    const dt = new Date(Date.UTC(y, m - 1, d - 1));\r\n    go(dt.toISOString().slice(0, 10));\r\n  });\r\n  $(\"#dy-next\").addEventListener(\"click\", () => {\r\n    const [y, m, d] = DY.date.split(\"-\").map(Number);\r\n    const dt = new Date(Date.UTC(y, m - 1, d + 1));\r\n    const iso = dt.toISOString().slice(0, 10);\r\n    if (iso <= todayLocal()) go(iso);\r\n  });\r\n  $(\"#dy-today\").addEventListener(\"click\", () => go(todayLocal()));\r\n  $(\"#dy-date\").addEventListener(\"change\", (e) => go(e.target.value));\r\n  $(\"#dy-save\").addEventListener(\"click\", saveDay);\r\n  const body = $(\"#dy-body\");\r\n  body.addEventListener(\"input\", (ev) => { const tr = ev.target.closest(\"tr[data-cid]\"); if (tr) { paintDayRow(tr); countDay(); } });\r\n  body.addEventListener(\"keydown\", (ev) => {\r\n    if (ev.key !== \"Enter\" || !ev.target.matches(\"input[data-f]\")) return;\r\n    ev.preventDefault();\r\n    const nxt = ev.target.closest(\"tr\").nextElementSibling;\r\n    const t = nxt ? nxt.querySelector(`input[data-f=\"${ev.target.dataset.f}\"]`) : null;\r\n    if (t) { t.focus(); t.select(); } else $(\"#dy-save\").focus();\r\n  });\r\n  renderDay();\r\n}\r\nasync function renderDay() {\r\n  const date = DY.date;\r\n  $(\"#dy-date\").value = date;\r\n  $(\"#dy-next\").disabled = date >= todayLocal();\r\n  const [y, m, d] = date.split(\"-\");\r\n  $(\"#dy-long\").textContent = `${d}/${m}/${y.slice(2)}`;\r\n  const box = $(\"#dy-body\");\r\n  try {\r\n    const { data } = await api(\"/api/entries?date=\" + date);\r\n    if (!data.length) {\r\n      box.innerHTML = `<div class=\"empty\"><strong>Nenhum criativo ativo</strong><span>Cadastre um criativo ou mude o status para Ativo/Escalando.</span><a class=\"btn\" href=\"#/cadastro\">Cadastrar criativo</a></div>`;\r\n      $(\"#dy-save\").disabled = true; $(\"#dy-count\").textContent = \"\";\r\n      return;\r\n    }\r\n    const cell = (f, val, mode, ph) => `<td><input class=\"ci\" data-f=\"${f}\" inputmode=\"${mode}\" value=\"${esc(val)}\" placeholder=\"${esc(ph)}\"></td>`;\r\n    box.innerHTML = `<table class=\"tbl daytbl\"><thead><tr><th>Criativo</th><th class=\"num\">Invest. (R$)</th><th class=\"num\">Vendas</th><th class=\"num\">Fatur. (R$)</th><th class=\"num\">Cliques Meta</th><th class=\"num\">Cliques Shopee</th><th class=\"num\">Custo</th><th class=\"num\">Lucro</th><th class=\"num\">CPC Meta</th><th class=\"num\">CPC Shopee</th><th>Saúde</th></tr></thead><tbody>${data.map((r) => {\r\n      const e = r.entry;\r\n      return `<tr data-cid=\"${r.creative.id}\" data-tax=\"${r.tax_rate}\" data-dia1=\"${esc(r.dia1 ?? \"\")}\"><td><div class=\"nm\">${esc(r.creative.name)}</div><div class=\"sub\">${esc(r.creative.product || \"—\")}</div></td>`\r\n        + cell(\"invest\", e ? fmtInputCents(e.investment_cents) : \"\", \"decimal\", \"0,00\")\r\n        + cell(\"sales\", e ? String(e.sales) : \"\", \"numeric\", \"0\")\r\n        + cell(\"rev\", e && e.revenue_cents != null ? fmtInputCents(e.revenue_cents) : \"\", \"decimal\", \"pendente\")\r\n        + cell(\"clM\", e ? String(e.clicks_meta) : \"\", \"numeric\", \"0\")\r\n        + cell(\"clS\", e ? String(e.clicks_shopee) : \"\", \"numeric\", \"0\")\r\n        + `<td class=\"calc\" data-c=\"cost\">—</td><td class=\"calc\" data-c=\"profit\">—</td><td class=\"calc\" data-c=\"cpcM\">—</td><td class=\"calc\" data-c=\"cpcS\">—</td><td class=\"mut\" data-c=\"health\">—</td></tr>`;\r\n    }).join(\"\")}</tbody></table>`;\r\n    $$(\"#dy-body tr[data-cid]\").forEach(paintDayRow);\r\n    countDay();\r\n    const w = $(\"#dy-warn\"); if (w) w.hidden = true;\r\n  } catch {\r\n    box.innerHTML = `<div class=\"empty\"><strong>Não foi possível carregar o dia</strong></div>`;\r\n  }\r\n}\r\nfunction paintDayRow(tr) {\r\n  const tax = Number(tr.dataset.tax || 0.1386);\r\n  const date = DY.date;\r\n  const dia1 = tr.dataset.dia1 || null;\r\n  const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\r\n  const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\r\n  const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\r\n  const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\r\n  const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\r\n  const invC = inv == null ? 0 : inv;\r\n  const salesN = sales == null ? 0 : sales;\r\n  const clMN = clM == null ? 0 : clM;\r\n  const clSN = clS == null ? 0 : clS;\r\n  const bad = [inv, sales, clM, clS].some((v) => typeof v === \"number\" && Number.isNaN(v)) || (rev != null && Number.isNaN(rev));\r\n  // Módulo único de cálculo (spec #6): custo/lucro/CPCs/pendente vêm do Calc.\r\n  const row = bad ? null : Calc.calcRow({ date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax });\r\n  const cost = row ? row.cost_cents : null;\r\n  const isPending = row ? row.is_pending : false;\r\n  const profit = row ? row.profit_cents : null;\r\n  const cpcM = row ? row.cpc_meta_cents : null;\r\n  const cpcS = row ? row.cpc_shopee_cents : null;\r\n  $('[data-c=\"cost\"]', tr).textContent = Calc.formatBRL(cost);\r\n  const pEl = $('[data-c=\"profit\"]', tr);\r\n  pEl.textContent = isPending ? \"pendente\" : Calc.formatBRL(profit);\r\n  pEl.className = \"calc\" + (profit == null || isPending ? \"\" : profit >= 0 ? \" prof good\" : \" prof bad\");\r\n  $('[data-c=\"cpcM\"]', tr).textContent = Calc.formatCPC(cpcM);\r\n  $('[data-c=\"cpcS\"]', tr).textContent = Calc.formatCPC(cpcS);\r\n  const hEl = $('[data-c=\"health\"]', tr);\r\n  const dayForSignal = { date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax };\r\n  if (bad || !Calc.hasMovement(dayForSignal)) { hEl.textContent = \"—\"; return; }\r\n  try {\r\n    const isDia1 = !dia1 || date <= dia1;\r\n    const sig = Calc.evaluateDay(dayForSignal, isDia1);\r\n    hEl.textContent = sig.saude === \"atencao\" ? `Atenção · ${sig.motivo ?? \"\"}` : (sig.motivo ?? \"Saudável\");\r\n  } catch { hEl.textContent = \"—\"; }\r\n}\r\nconst rowFilled = (tr) => [\"invest\", \"sales\", \"rev\", \"clM\", \"clS\"].some((f) => $('[data-f=\"' + f + '\"]', tr).value.trim() !== \"\");\r\nfunction countDay() {\r\n  const rows = $$(\"#dy-body tr[data-cid]\");\r\n  if (!rows.length) return;\r\n  const n = rows.filter(rowFilled).length;\r\n  $(\"#dy-count\").textContent = `${n} de ${rows.length} preenchidos`;\r\n  $(\"#dy-save\").disabled = n === 0;\r\n}\r\nasync function saveDay() {\r\n  const rows = $$(\"#dy-body tr[data-cid]\");\r\n  const entries = [];\r\n  $$(\"#dy-body .ci.bad\").forEach((i) => i.classList.remove(\"bad\"));\r\n  for (const tr of rows) {\r\n    if (!rowFilled(tr)) continue;\r\n    const cid = Number(tr.dataset.cid);\r\n    const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\r\n    const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\r\n    const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\r\n    const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\r\n    const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\r\n    const name = $(\".nm\", tr).textContent;\r\n    const mark = (f) => $('[data-f=\"' + f + '\"]', tr).classList.add(\"bad\");\r\n    let bad = false;\r\n    for (const [f, v] of [[\"invest\", inv], [\"sales\", sales], [\"rev\", rev], [\"clM\", clM], [\"clS\", clS]]) {\r\n      if (typeof v === \"number\" && Number.isNaN(v)) { mark(f); bad = true; }\r\n      if (typeof v === \"number\" && v != null && v < 0) { mark(f); bad = true; }\r\n    }\r\n    for (const [f, v] of [[\"sales\", sales], [\"clM\", clM], [\"clS\", clS]]) {\r\n      if (typeof v === \"number\" && v != null && !Number.isInteger(v)) { mark(f); bad = true; }\r\n    }\r\n    if (bad) { toast(`Confira os números de ${name}.`); return; }\r\n    entries.push({ creative_id: cid, investment_cents: inv ?? 0, sales: sales ?? 0, revenue_cents: rev, clicks_meta: clM ?? 0, clicks_shopee: clS ?? 0 });\r\n  }\r\n  if (!entries.length) { toast(\"Preencha ao menos um criativo.\"); return; }\r\n  try {\r\n    const { warnings } = await api(\"/api/entries/bulk\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ date: DY.date, entries }) });\r\n    const w = $(\"#dy-warn\");\r\n    if (warnings?.length) { w.textContent = warnings.join(\" \"); w.hidden = false; }\r\n    else if (w) w.hidden = true;\r\n    toast(`${entries.length} ${entries.length === 1 ? \"lançamento salvo\" : \"lançamentos salvos\"} em ${fDate(DY.date)}`);\r\n    renderDay();\r\n  } catch (e) {\r\n    toast(e.body?.error === \"encerrado_sem_lancamento\" ? \"Criativo encerrado não recebe lançamentos.\" : \"Não foi possível salvar. Confira os números (nada negativo; vendas/cliques inteiros).\");\r\n  }\r\n}\r\n\r\n// ---------- Dashboard de decisão (T5) ----------\r\n// Filtros: período, Criativos, status, produto, decisão. Resumo com variação\r\n// contra o período anterior + aviso de pendentes. Gráfico diário SVG\r\n// (custo, faturamento, lucro/prejuízo, faixa nos dias pendentes).\r\n// Tabela de decisão ordenável com clique abrindo o detalhe.\r\nconst D = { preset: \"30d\", from: \"\", to: \"\", ids: new Set(), status: \"all\", product: \"all\", decision: \"all\", sort: { k: \"profit\", dir: -1 }, data: null, products: [] };\r\nconst PRESETS = [[\"today\",\"Hoje\"],[\"yesterday\",\"Ontem\"],[\"7d\",\"Últimos 7 dias\"],[\"14d\",\"Últimos 14 dias\"],[\"30d\",\"Últimos 30 dias\"],[\"month\",\"Este mês\"],[\"lastmonth\",\"Mês passado\"],[\"all\",\"Todo o período\"],[\"custom\",\"Personalizado\"]];\r\nfunction dAddDays(iso, n) { const [y,m,d] = iso.split(\"-\").map(Number); return new Date(Date.UTC(y,m-1,d+n)).toISOString().slice(0,10); }\r\nfunction dPresetRange() {\r\n  const t = todayLocal();\r\n  switch (D.preset) {\r\n    case \"today\": return [t, t];\r\n    case \"yesterday\": return [dAddDays(t,-1), dAddDays(t,-1)];\r\n    case \"7d\": return [dAddDays(t,-6), t];\r\n    case \"14d\": return [dAddDays(t,-13), t];\r\n    case \"30d\": return [dAddDays(t,-29), t];\r\n    case \"month\": return [t.slice(0,8)+\"01\", t];\r\n    case \"lastmonth\": { const first = t.slice(0,8)+\"01\"; const [y,m] = first.split(\"-\").map(Number); const prev = new Date(Date.UTC(y,m-2,1)); const pf = prev.toISOString().slice(0,10); return [pf.slice(0,8)+\"01\", dAddDays(first,-1)]; }\r\n    case \"all\": return [null, null];\r\n    default: return [D.from || t, D.to || t];\r\n  }\r\n}\r\nfunction deltaHtml(cur, prev, invert) {\r\n  if (cur == null || prev == null) return \"\";\r\n  if (prev === 0) return cur === 0 ? '<span class=\"dl n\">= estável</span>' : \"\";\r\n  const p = (cur - prev) / Math.abs(prev) * 100;\r\n  if (Math.abs(p) < 0.5) return '<span class=\"dl n\">= estável</span>';\r\n  const up = p > 0;\r\n  const good = invert ? !up : up;\r\n  return `<span class=\"dl ${good ? \"g\" : \"b\"}\">${up ? \"▲\" : \"▼\"} ${Math.abs(p).toLocaleString(\"pt-BR\",{maximumFractionDigits:0})}%</span>`;\r\n}\r\nasync function pageDashboard() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Dashboard</h1><p class=\"sub\" id=\"dash-sub\">Decida olhando o painel</p></div><a class=\"btn\" href=\"#/lancamento\">Lançar dados do dia</a></div>\r\n  <div class=\"fb\" role=\"group\" aria-label=\"Filtros do dashboard\">\r\n    <div class=\"dd\" id=\"dd-period\"><button class=\"ctl\" type=\"button\" id=\"dd-period-btn\" aria-haspopup=\"true\">📅 <span id=\"lbl-period\">Período</span></button>\r\n      <div class=\"dd-menu\" id=\"dd-period-menu\">${PRESETS.filter((p)=>p[0]!==\"custom\").map((p)=>`<button type=\"button\" class=\"dd-item\" data-preset=\"${p[0]}\">${p[1]}</button>`).join(\"\")}<div style=\"display:flex;gap:6px;margin-top:6px\"><label>De <input type=\"date\" class=\"in sm\" id=\"f-from\"></label><label>Até <input type=\"date\" class=\"in sm\" id=\"f-to\"></label></div></div></div>\r\n    <div class=\"dd\" id=\"dd-cr\"><button class=\"ctl\" type=\"button\">Criativo: <span id=\"lbl-cr\">Todos</span></button>\r\n      <div class=\"dd-menu\" style=\"min-width:280px\"><input class=\"in sm\" style=\"width:100%\" id=\"cr-q\" placeholder=\"Buscar criativo…\" aria-label=\"Buscar criativo\"><div class=\"dd-list\" id=\"cr-list\"></div><div><button class=\"lnk\" type=\"button\" id=\"cr-clear\">Limpar seleção</button></div></div></div>\r\n    <label class=\"ctl\">Status <select id=\"f-status\"><option value=\"all\">Todos</option>${Object.entries(STATUS).map(([k,v])=>`<option value=\"${k}\">${v}</option>`).join(\"\")}</select></label>\r\n    <label class=\"ctl\">Produto <select id=\"f-product\"><option value=\"all\">Todos</option></select></label>\r\n    <label class=\"ctl\">Decisão <select id=\"f-dec\"><option value=\"all\">Todas</option><option value=\"saudavel\">Saudável</option><option value=\"atencao\">Atenção</option><option value=\"escalando\">Escalando</option><option value=\"pausado\">Pausado</option><option value=\"encerrado\">Encerrado</option><option value=\"sem_dados\">Sem dados</option></select></label>\r\n    <button class=\"lnk\" type=\"button\" id=\"f-clear\" hidden>Limpar filtros</button>\r\n  </div>\r\n  <div id=\"dash-res\"><div class=\"panel\"><div class=\"panel-b mut\">Carregando…</div></div></div>`;\r\n  try {\r\n    const { data } = await api(\"/api/creatives?sort=name\");\r\n    D.products = [...new Set(data.map((c)=>c.product).filter(Boolean))].sort((a,b)=>a.localeCompare(b,\"pt-BR\"));\r\n    const sel = $(\"#f-product\");\r\n    sel.innerHTML = `<option value=\"all\">Todos</option>` + D.products.map((p)=>`<option>${esc(p)}</option>`).join(\"\");\r\n    sel.value = D.product;\r\n    const list = $(\"#cr-list\");\r\n    list.innerHTML = data.map((c)=>`<label class=\"dd-opt\" data-name=\"${esc(c.name.toLowerCase())}\"><input type=\"checkbox\" value=\"${c.id}\" ${D.ids.has(c.id)?\"checked\":\"\"}><span>${esc(c.name)}</span><small>${STATUS[c.status]??c.status}</small></label>`).join(\"\");\r\n  } catch {}\r\n  $(\"#f-status\").value = D.status; $(\"#f-dec\").value = D.decision;\r\n  const btn = $(\"#dd-period-btn\");\r\n  btn.addEventListener(\"click\", () => $(\"#dd-period\").classList.toggle(\"open\"));\r\n  $(\"#dd-period-menu\").addEventListener(\"click\", (e) => { const it = e.target.closest(\"[data-preset]\"); if (!it) return; D.preset = it.dataset.preset; $(\"#dd-period\").classList.remove(\"open\"); loadDashboard(); });\r\n  const range = () => { D.preset = \"custom\"; D.from = $(\"#f-from\").value; D.to = $(\"#f-to\").value; loadDashboard(); };\r\n  $(\"#f-from\").addEventListener(\"change\", range); $(\"#f-to\").addEventListener(\"change\", range);\r\n  const crBtn = $(\"#dd-cr .ctl\");\r\n  crBtn.addEventListener(\"click\", () => $(\"#dd-cr\").classList.toggle(\"open\"));\r\n  $(\"#cr-list\").addEventListener(\"change\", (e) => { const id = Number(e.target.value); if (e.target.checked) D.ids.add(id); else D.ids.delete(id); loadDashboard(); });\r\n  $(\"#cr-q\").addEventListener(\"input\", (e) => { const q = e.target.value.trim().toLowerCase(); $$(\"#cr-list .dd-opt\").forEach((o)=>{ o.hidden = q && !o.dataset.name.includes(q); }); });\r\n  $(\"#cr-clear\").addEventListener(\"click\", () => { D.ids.clear(); loadDashboard(); });\r\n  $(\"#f-status\").addEventListener(\"change\", (e) => { D.status = e.target.value; loadDashboard(); });\r\n  $(\"#f-product\").addEventListener(\"change\", (e) => { D.product = e.target.value; loadDashboard(); });\r\n  $(\"#f-dec\").addEventListener(\"change\", (e) => { D.decision = e.target.value; loadDashboard(); });\r\n  $(\"#f-clear\").addEventListener(\"click\", () => { Object.assign(D, { preset:\"30d\", from:\"\", to:\"\", status:\"all\", product:\"all\", decision:\"all\" }); D.ids.clear(); D.sort = { k:\"profit\", dir:-1 }; pageDashboard(); });\r\n  $(\"#dash-res\").addEventListener(\"click\", (e) => {\r\n    const th = e.target.closest(\"th[data-sort]\");\r\n    if (th) { const k = th.dataset.sort; D.sort = { k, dir: D.sort.k === k ? -D.sort.dir : -1 }; renderDashTable(); return; }\r\n    const tr = e.target.closest(\"tr[data-id]\");\r\n    if (tr) location.hash = \"#/criativo/\" + tr.dataset.id;\r\n    if (e.target.closest(\"[data-reset]\")) $(\"#f-clear\").click();\r\n  });\r\n  document.addEventListener(\"click\", (e) => { if (!e.target.closest(\".dd\")) $$(\".dd.open\").forEach((d)=>d.classList.remove(\"open\")); }, { once: true });\r\n  await loadDashboard();\r\n}\r\nasync function loadDashboard() {\r\n  const box = $(\"#dash-res\");\r\n  try {\r\n    const [from, to] = dPresetRange();\r\n    const qs = new URLSearchParams();\r\n    if (D.preset === \"all\") qs.set(\"all\", \"1\");\r\n    else { qs.set(\"from\", from); qs.set(\"to\", to); }\r\n    if (D.ids.size) qs.set(\"creatives\", [...D.ids].join(\",\"));\r\n    if (D.status !== \"all\") qs.set(\"status\", D.status);\r\n    if (D.product !== \"all\") qs.set(\"product\", D.product);\r\n    if (D.decision !== \"all\") qs.set(\"decision\", D.decision);\r\n    const { data, warnings } = await api(\"/api/dashboard?\" + qs.toString());\r\n    D.data = { ...data, warnings };\r\n    if (D.preset !== \"all\") { $(\"#f-from\").value = data.period.from; $(\"#f-to\").value = data.period.to; D.from = data.period.from; D.to = data.period.to; }\r\n    const lbl = PRESETS.find((p)=>p[0]===D.preset);\r\n    $(\"#lbl-period\").textContent = D.preset === \"all\" ? \"Todo o período\" : `${lbl ? lbl[1] : \"Personalizado\"} · ${fDate(data.period.from)}–${fDate(data.period.to)}`;\r\n    $(\"#lbl-cr\").textContent = !D.ids.size ? \"Todos\" : D.ids.size === 1 ? (data.creatives.find((c)=>D.ids.has(c.creative.id))?.creative.name ?? \"1 selecionado\") : `${D.ids.size} selecionados`;\r\n    $(\"#f-clear\").hidden = D.preset === \"30d\" && !D.ids.size && D.status === \"all\" && D.product === \"all\" && D.decision === \"all\";\r\n    renderDashboard();\r\n  } catch {\r\n    if (box) box.innerHTML = `<div class=\"panel\"><div class=\"empty\"><strong>Não foi possível carregar o dashboard</strong></div></div>`;\r\n  }\r\n}\r\nfunction renderDashboard() {\r\n  const d = D.data;\r\n  if (!d) return;\r\n  if (!d.creatives.length) {\r\n    $(\"#dash-res\").innerHTML = `<div class=\"panel\"><div class=\"empty\"><strong>Nenhum lançamento encontrado</strong><span>Não há dados neste período com os filtros escolhidos.</span><button class=\"btn ghost\" type=\"button\" data-reset>Limpar filtros</button></div></div>`;\r\n    return;\r\n  }\r\n  const t = d.totals, p = d.previousTotals;\r\n  const profCls = t.profit_cents == null ? \"\" : t.profit_cents >= 0 ? \"good\" : \"bad\";\r\n  const kpi = (lbl, big, sub, dl) => `<div class=\"kpi\"><div class=\"lbl\">${lbl}</div><div class=\"big ${profCls && lbl.includes(\"Lucro\") ? profCls : \"\"}\">${big}</div><div class=\"sub2\">${sub} ${dl ?? \"\"}</div></div>`;\r\n  const pendNote = t.has_pending ? `<div class=\"warnbox\">⚠ ${esc((d.warnings||[]).join(\" \") || `${t.pending_days} dia(s) com faturamento pendente — fora do lucro até preencher.`)} </div>` : \"\";\r\n  $(\"#dash-res\").innerHTML = `\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <div style=\"display:flex;gap:16px;align-items:baseline;flex-wrap:wrap;margin-bottom:12px\"><span class=\"mut\">Lucro no período</span><strong class=\"prof ${profCls}\" style=\"font-size:28px\">${t.profit_cents == null ? (t.has_pending ? \"pendente\" : \"—\") : fBRL(t.profit_cents)}</strong>${deltaHtml(t.profit_cents, p?.profit_cents ?? null)}${p ? '<span class=\"mut\">vs período anterior</span>' : \"\"}</div>\r\n    <div class=\"kpis\">\r\n      ${kpi(\"Investimento\", fBRL(t.investment_cents), `custo ${fBRL(t.cost_cents)}`, deltaHtml(t.investment_cents, p?.investment_cents ?? null, true))}\r\n      ${kpi(\"Faturamento\", t.costClosed_cents > 0 ? fBRL(t.revenue_cents) : \"—\", t.has_pending ? `${t.pending_days} dia(s) pendente(s)` : \"\", deltaHtml(t.revenue_cents, p?.revenue_cents ?? null))}\r\n      ${kpi(\"Vendas\", String(t.sales), \"\", deltaHtml(t.sales, p?.sales ?? null))}\r\n      ${kpi(\"ROAS-equiv.\", t.roas_equivalente == null ? \"—\" : Calc.formatRoas(t.roas_equivalente), \"fatur ÷ custo\", deltaHtml(t.roas_equivalente, p?.roas_equivalente ?? null))}\r\n      ${kpi(\"CPC Meta\", Calc.formatCPC(t.cpc_meta_cents), \"invest ÷ cliques\", deltaHtml(t.cpc_meta_cents, p?.cpc_meta_cents ?? null, true))}\r\n      ${kpi(\"CPC Shopee\", Calc.formatCPC(t.cpc_shopee_cents), \"invest ÷ cliques\", deltaHtml(t.cpc_shopee_cents, p?.cpc_shopee_cents ?? null, true))}\r\n    </div>\r\n    ${pendNote}\r\n  </div></section>\r\n  <section class=\"panel\"><div class=\"panel-h\"><h2>Evolução diária</h2><span class=\"mut\">custo · faturamento · lucro/prejuízo · faixa nos dias pendentes</span></div><div class=\"panel-b\" id=\"chart-box\"></div></section>\r\n  <section class=\"panel\"><div class=\"panel-h\"><h2>Decisão por criativo</h2><span class=\"mut\">clique abre o detalhe</span></div><div class=\"scroll\" id=\"dash-tbl\"></div>\r\n  <div class=\"foot-note\">Ordene por lucro, ROAS-equiv., custo ou vendas clicando no cabeçalho. A cor vem do Sinal (régua + Status + Motivo), nunca do ROAS.</div></section>`;\r\n  drawChart($(\"#chart-box\"), d.daily);\r\n  renderDashTable();\r\n}\r\nfunction renderDashTable() {\r\n  const d = D.data;\r\n  if (!d) return;\r\n  const rows = [...d.creatives].sort((x, y) => {\r\n    const g = (r) => ({ profit: r.totals.profit_cents, roas: r.totals.roas_equivalente, cost: r.totals.cost_cents, sales: r.totals.sales })[D.sort.k];\r\n    const a = g(x), b = g(y);\r\n    if (a == null && b == null) return 0; if (a == null) return 1; if (b == null) return -1;\r\n    return (a - b) * D.sort.dir;\r\n  });\r\n  const th = (k, label) => `<th class=\"num\" data-sort=\"${k}\">${label}${D.sort.k === k ? `<span class=\"ar\">${D.sort.dir < 0 ? \"↓\" : \"↑\"}</span>` : \"\"}</th>`;\r\n  $(\"#dash-tbl\").innerHTML = `<table class=\"tbl\"><thead><tr><th>Criativo</th><th>Status</th><th>Saúde</th>${th(\"profit\",\"Lucro\")}${th(\"roas\",\"ROAS-equiv.\")}${th(\"cost\",\"Custo\")}${th(\"sales\",\"Vendas\")}<th>Motivo</th></tr></thead><tbody>${rows.map((r) => {\r\n    const pc = profitClass(r.totals.profit_cents);\r\n    return `<tr class=\"click\" data-id=\"${r.creative.id}\"><td><div class=\"nm\">${esc(r.creative.name)}</div><div class=\"sub\">${esc(r.creative.product||\"—\")}</div></td><td>${chipFor(r.health)}</td><td>${rulerFor(r.health)}</td><td class=\"num prof ${pc}\">${r.totals.profit_cents == null ? (r.totals.has_pending ? \"pendente\" : \"—\") : fBRL(r.totals.profit_cents)}</td><td class=\"num\">${r.totals.roas_equivalente == null ? \"—\" : Calc.formatRoas(r.totals.roas_equivalente)}</td><td class=\"num\">${fBRL(r.totals.cost_cents)}</td><td class=\"num\">${r.totals.sales}</td><td class=\"mut\">${esc(r.health.motivo ?? \"—\")}</td></tr>`;\r\n  }).join(\"\")}</tbody></table>`;\r\n}\r\nfunction drawChart(box, days) {\r\n  if (!box) return;\r\n  const W = Math.max(box.clientWidth || 600, 320), H = 220, P = { l: 56, r: 12, t: 12, b: 26 };\r\n  const iw = W - P.l - P.r, ih = H - P.t - P.b;\r\n  const vals = [];\r\n  for (const d of days) { if (d.empty) continue; vals.push(d.cost_cents, d.revenue_cents ?? 0, d.profit_cents ?? 0); }\r\n  const max = Math.max(1, ...vals.map((v)=>Math.abs(v)));\r\n  const n = days.length;\r\n  const x = (i) => P.l + (n === 1 ? iw / 2 : (i / (n - 1)) * iw);\r\n  const y = (v) => P.t + ih / 2 - (v / max) * (ih / 2 - 4);\r\n  const bw = n ? Math.min(18, iw / Math.max(n,1) * 0.4) : 8;\r\n  let s = `<svg class=\"chart\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Gráfico diário\">`;\r\n  s += `<line x1=\"${P.l}\" y1=\"${y(0)}\" x2=\"${W-P.r}\" y2=\"${y(0)}\" stroke=\"#D8DFDC\"/>`;\r\n  days.forEach((d, i) => {\r\n    if (d.pending && !d.empty) s += `<rect x=\"${x(i)-bw}\" y=\"${P.t}\" width=\"${bw*2}\" height=\"${ih}\" fill=\"#F6E8BE\" opacity=\"0.55\"><title>${fDate(d.date)} · pendente</title></rect>`;\r\n  });\r\n  days.forEach((d, i) => {\r\n    if (d.empty) return;\r\n    const p = d.profit_cents ?? 0;\r\n    const y0 = y(0), y1 = y(p);\r\n    s += `<rect x=\"${x(i)-bw/2}\" y=\"${Math.min(y0,y1)}\" width=\"${bw}\" height=\"${Math.max(2,Math.abs(y1-y0))}\" fill=\"${p >= 0 ? \"#2FBF7A\" : \"#E5595B\"}\"><title>${fDate(d.date)} · lucro ${d.profit_cents == null ? \"pendente\" : (d.profit_cents/100).toLocaleString(\"pt-BR\",{style:\"currency\",currency:\"BRL\"})}</title></rect>`;\r\n  });\r\n  const line = (get, color) => {\r\n    const pts = days.map((d, i) => d.empty ? null : `${x(i).toFixed(1)},${y(get(d) ?? 0).toFixed(1)}`).filter(Boolean);\r\n    if (pts.length < 2) return \"\";\r\n    return `<polyline points=\"${pts.join(\" \")}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2\"/>`;\r\n  };\r\n  s += line((d)=>d.cost_cents, \"#16201C\");\r\n  s += line((d)=>d.revenue_cents ?? 0, \"#0E76B8\");\r\n  days.forEach((d, i) => { if (i % Math.ceil(n/6) === 0) s += `<text x=\"${x(i)}\" y=\"${H-8}\" font-size=\"10\" text-anchor=\"middle\" fill=\"#647570\">${fDate(d.date)}</text>`; });\r\n  s += `<g font-size=\"11\"><circle cx=\"${P.l+6}\" cy=\"8\" r=\"4\" fill=\"#16201C\"/><text x=\"${P.l+14}\" y=\"12\" fill=\"#16201C\">Custo</text><circle cx=\"${P.l+70}\" cy=\"8\" r=\"4\" fill=\"#0E76B8\"/><text x=\"${P.l+78}\" y=\"12\" fill=\"#16201C\">Faturamento</text><rect x=\"${P.l+168}\" y=\"4\" width=\"10\" height=\"8\" fill=\"#2FBF7A\"/><rect x=\"${P.l+180}\" y=\"4\" width=\"10\" height=\"8\" fill=\"#E5595B\"/><text x=\"${P.l+194}\" y=\"12\" fill=\"#16201C\">Lucro/prejuízo</text></g>`;\r\n  s += `</svg>`;\r\n  box.innerHTML = s;\r\n}\r\n\r\n// ---------- Config: imposto + backup/export (T5) ----------\r\nasync function pageConfig() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Configurações</h1><p class=\"sub\">Imposto, backup e dados</p></div></div>\r\n  <div class=\"cols\">\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <h2 style=\"margin:0 0 8px\">Imposto (%)</h2>\r\n    <p class=\"hint\">Taxa usada nos próximos lançamentos. Dias antigos ficam intactos (cada dia guarda a própria taxa).</p>\r\n    <div class=\"fld\"><label for=\"cfg-tax\">Taxa atual (%)</label><input class=\"in\" id=\"cfg-tax\" inputmode=\"decimal\" placeholder=\"13,86\"><span class=\"hint\">Aceita 13,86 ou 13.86 (= 13,86%).</span><div class=\"err-msg\" id=\"cfg-tax-err\" hidden></div></div>\r\n    <div class=\"actions\"><button class=\"btn\" id=\"cfg-save\" type=\"button\">Salvar imposto</button></div>\r\n  </div></section>\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <h2 style=\"margin:0 0 8px\">Backup e dados</h2>\r\n    <p class=\"hint\" id=\"cfg-path\">Caminho do arquivo: carregando…</p>\r\n    <div class=\"actions\"><button class=\"btn\" id=\"cfg-backup\" type=\"button\">Fazer backup agora</button><button class=\"btn ghost\" id=\"cfg-export\" type=\"button\">Exportar dados (JSON)</button></div>\r\n    <div style=\"height:12px\"></div>\r\n    <strong>Últimos backups (30 mantidos)</strong>\r\n    <ul class=\"recent\" id=\"cfg-backs\"><li class=\"mut\">Carregando…</li></ul>\r\n  </div></section>\r\n  </div>`;\r\n  try {\r\n    const [{ data: s }, info] = await Promise.all([api(\"/api/settings\"), api(\"/api/info\")]);\r\n    $(\"#cfg-tax\").value = (s.tax_rate * 100).toLocaleString(\"pt-BR\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\r\n    $(\"#cfg-path\").textContent = `Caminho do arquivo: ${info.data.dbPath} (pasta ${info.data.dataDir}) — backups diários em backups/, 30 últimos.`;\r\n  } catch { $(\"#cfg-path\").textContent = \"Não foi possível ler o caminho do arquivo.\"; }\r\n  $(\"#cfg-save\").addEventListener(\"click\", async () => {\r\n    const err = $(\"#cfg-tax-err\");\r\n    err.hidden = true;\r\n    try {\r\n      const { data } = await api(\"/api/settings\", { method: \"PUT\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ tax_rate: $(\"#cfg-tax\").value }) });\r\n      $(\"#cfg-tax\").value = (data.tax_rate * 100).toLocaleString(\"pt-BR\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\r\n      toast(`Imposto atualizado para ${(data.tax_rate*100).toLocaleString(\"pt-BR\")}% — dias antigos intactos.`);\r\n    } catch (e) { err.textContent = \"Valor inválido. Use algo como 13,86.\"; err.hidden = false; }\r\n  });\r\n  $(\"#cfg-backup\").addEventListener(\"click\", async () => {\r\n    try { const { data } = await api(\"/api/backup\", { method: \"POST\" }); toast(`Backup criado: ${data.file}`); await loadBacks(); }\r\n    catch { toast(\"Não foi possível criar o backup.\"); }\r\n  });\r\n  $(\"#cfg-export\").addEventListener(\"click\", async () => {\r\n    try {\r\n      const { data } = await api(\"/api/export\");\r\n      const blob = new Blob([JSON.stringify(data, null, 2)], { type: \"application/json\" });\r\n      const a = document.createElement(\"a\");\r\n      a.href = URL.createObjectURL(blob);\r\n      a.download = `gestor-export-${todayLocal()}.json`;\r\n      a.click();\r\n      setTimeout(() => URL.revokeObjectURL(a.href), 2000);\r\n      toast(\"Dados exportados.\");\r\n    } catch { toast(\"Não foi possível exportar.\"); }\r\n  });\r\n  async function loadBacks() {\r\n    try {\r\n      const { data } = await api(\"/api/backups\");\r\n      $(\"#cfg-backs\").innerHTML = data.length ? data.slice(0,30).map((b)=>`<li><span>${esc(b.file)}</span><span class=\"mut\">${b.size != null ? (b.size/1024).toLocaleString(\"pt-BR\",{maximumFractionDigits:0}) + \" KB\" : \"\"}</span></li>`).join(\"\") : `<li class=\"mut\">Nenhum backup ainda.</li>`;\r\n    } catch { $(\"#cfg-backs\").innerHTML = `<li class=\"mut\">—</li>`; }\r\n  }\r\n  await loadBacks();\r\n}\r\n\r\nfunction router() {\r\n  $$(\".nav a\").forEach((a) => a.removeAttribute(\"aria-current\"));\r\n  const h = location.hash || \"#/dashboard\";\r\n  if (h.startsWith(\"#/cadastro\")) { $('[data-nav=\"cadastro\"]').setAttribute(\"aria-current\",\"page\"); pageRegister(); }\r\n  else if (h.startsWith(\"#/criativo/\")) { $('[data-nav=\"criativos\"]').setAttribute(\"aria-current\",\"page\"); pageDetail(h.split(\"/\")[2]); }\r\n  else if (h.startsWith(\"#/lancamento\")) { $('[data-nav=\"lancamento\"]').setAttribute(\"aria-current\",\"page\"); pageDaily(); }\r\n  else if (h.startsWith(\"#/criativos\")) { $('[data-nav=\"criativos\"]').setAttribute(\"aria-current\",\"page\"); pageLibrary(); }\r\n  else if (h.startsWith(\"#/config\")) { $('[data-nav=\"config\"]').setAttribute(\"aria-current\",\"page\"); pageConfig(); }\r\n  else { $('[data-nav=\"dashboard\"]').setAttribute(\"aria-current\",\"page\"); pageDashboard(); }\r\n}\r\nwindow.addEventListener(\"hashchange\", router);\r\nrouter();\r\n</script>\r\n</body>\r\n</html>\r\n", binary: undefined },
};
export const INDEX_HTML: string = "<!DOCTYPE html>\r\n<html lang=\"pt-BR\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>Gestor de Tráfego Pago</title>\r\n<style>\r\n:root{--bg:#EBEFED;--surface:#fff;--ink:#16201C;--muted:#647570;--line:#D8DFDC;--btn:#16201C;--btn-ink:#fff;\r\n--good:#0B8A4C;--good-bg:#D9F2E4;--good-seg:#2FBF7A;--ok:#0E76B8;--ok-bg:#D8ECF9;--ok-seg:#3AA6E6;\r\n--warn:#8A5F00;--warn-bg:#F6E8BE;--warn-seg:#E2AE1F;--bad:#B72929;--bad-bg:#F8DADA;--bad-seg:#E5595B;--wait-bg:#E3E9E6;--wait:#5D6D68}\r\n*{box-sizing:border-box}\r\nbody{margin:0;background:var(--bg);color:var(--ink);font:400 14px/1.45 system-ui,\"Segoe UI\",Roboto,Arial,sans-serif;padding:0}\r\n.app{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:100vh}\r\n.side{background:var(--surface);border-right:1px solid var(--line);padding:18px 12px;display:flex;flex-direction:column;gap:2px;position:sticky;top:0;height:100vh}\r\n.brand{font-weight:800;font-size:17px;padding:4px 10px 16px}\r\n.nav{display:flex;flex-direction:column;gap:2px}\r\n.nav a{padding:9px 10px;border-radius:9px;text-decoration:none;color:#3A4843;font-weight:600}\r\n.nav a[aria-current=\"page\"]{background:var(--btn);color:var(--btn-ink)}\r\n.main{padding:26px 28px 56px;min-width:0}\r\n.wrap{max-width:1100px;margin:0 auto}\r\n.ph{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:16px}\r\n.ph h1{margin:0;font-size:28px}\r\n.sub{color:var(--muted);font-size:13px;margin:4px 0 0}\r\n.panel{background:var(--surface);border:1px solid var(--line);border-radius:14px;margin-bottom:16px}\r\n.panel-b{padding:18px}\r\n.fb{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}\r\n.ctl{display:inline-flex;align-items:center;gap:8px;height:38px;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}\r\n.ctl input,.ctl select{border:0;background:transparent;outline:0}\r\n.ctl.search{min-width:240px}.ctl.search input{flex:1}\r\n.btn{display:inline-flex;align-items:center;gap:8px;height:38px;padding:0 14px;border-radius:9px;border:1px solid var(--btn);background:var(--btn);color:var(--btn-ink);font-weight:700;cursor:pointer;text-decoration:none}\r\n.btn.ghost{background:transparent;color:var(--ink);border-color:var(--line)}\r\n.btn:disabled{opacity:.4;cursor:not-allowed}\r\n.in{height:40px;width:100%;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}\r\ntextarea.in{height:auto;min-height:80px;padding:10px 12px;resize:vertical}\r\n.in.err{border-color:var(--bad)}\r\n.fld{display:grid;gap:6px;margin-bottom:14px}.fld>label{font-weight:700}\r\n.hint{font-size:12.5px;color:var(--muted)}\r\n.err-msg{font-size:13px;color:var(--bad);font-weight:700}\r\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:9px;padding:3px;background:#F4F7F6;gap:2px}\r\n.seg button{height:32px;padding:0 14px;border:0;border-radius:7px;background:transparent;cursor:pointer;font-weight:600}\r\n.seg button[aria-pressed=\"true\"]{background:var(--surface);box-shadow:0 0 0 1px var(--line)}\r\n.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}\r\n.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}\r\n.tbl{width:100%;border-collapse:collapse}\r\n.tbl th{font-size:12px;color:var(--muted);text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap}\r\n.tbl td{padding:11px 12px;border-bottom:1px solid #E8EDEB;vertical-align:middle}\r\n.tbl tr.click{cursor:pointer}.tbl tr.click:hover td{background:#F4F7F6}\r\n.tbl td.num,.tbl th.num{text-align:right}\r\n.nm{font-weight:700}\r\n.chip{display:inline-flex;align-items:center;height:24px;padding:0 10px;border-radius:99px;font-size:12px;font-weight:800;white-space:nowrap}\r\n.chip.good{background:var(--good-bg);color:var(--good)}.chip.ok{background:var(--ok-bg);color:var(--ok)}\r\n.chip.warn{background:var(--warn-bg);color:var(--warn)}.chip.bad{background:var(--bad-bg);color:var(--bad)}\r\n.chip.wait{background:var(--wait-bg);color:var(--wait)}\r\n.ruler{position:relative;display:inline-grid;grid-template-columns:repeat(4,1fr);gap:2px;width:104px;height:8px;vertical-align:middle}\r\n.ruler i{border-radius:2px}.ruler i:nth-child(1){background:var(--bad-seg)}.ruler i:nth-child(2){background:var(--warn-seg)}\r\n.ruler i:nth-child(3){background:var(--ok-seg)}.ruler i:nth-child(4){background:var(--good-seg)}\r\n.ruler b{position:absolute;top:-5px;bottom:-5px;width:4px;margin-left:-2px;border-radius:2px;background:var(--ink);box-shadow:0 0 0 2px var(--surface)}\r\n.ruler.off i{background:var(--line)}\r\n.mut{color:var(--muted)}.prof.good{color:var(--good)}.prof.bad{color:var(--bad)}\r\n.recent{list-style:none;margin:0;padding:6px 0}.recent li{display:flex;justify-content:space-between;gap:10px;padding:10px 18px;border-bottom:1px solid #E8EDEB}\r\n.empty{padding:36px;text-align:center;color:var(--muted);display:grid;gap:10px;justify-items:center}\r\n.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,16px);background:var(--btn);color:var(--btn-ink);padding:11px 16px;border-radius:10px;font-weight:700;opacity:0;pointer-events:none;transition:opacity .18s,transform .18s;z-index:50}\r\n.toast.on{opacity:1;transform:translate(-50%,0)}\r\n.cols{display:grid;grid-template-columns:minmax(0,640px) minmax(260px,1fr);gap:16px;align-items:start}\r\n@media(max-width:900px){.app{grid-template-columns:1fr}.side{height:auto;position:static;flex-direction:row;align-items:center}.cols,.two{grid-template-columns:1fr}}\r\n.daybar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}\r\n.daybar .long{font-weight:700;font-size:17px;margin-left:8px}\r\n.daytbl td{padding:6px 8px}\r\n.ci{width:100%;min-width:76px;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:7px;background:var(--surface);text-align:right}\r\n.ci:focus{outline:0;border-color:var(--ink)}\r\n.ci.bad{border-color:var(--bad)}\r\n.ci::placeholder{color:var(--muted);font-style:italic}\r\n.daytbl td.calc{background:#F4F7F6;text-align:right;white-space:nowrap;padding:0 10px}\r\n.savebar{position:sticky;bottom:0;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 18px;background:var(--surface);border-top:1px solid var(--line);border-radius:0 0 14px 14px}\r\n.bulkprev{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}\r\n.bulkprev span{background:#F4F7F6;border:1px solid var(--line);border-radius:99px;padding:2px 10px;font-size:12.5px}\r\n.bulkprev span.dup{border-color:var(--bad);color:var(--bad)}\r\n.warnbox{display:flex;gap:8px;align-items:flex-start;margin:0 18px 12px;font-size:12.5px;color:var(--warn);background:var(--warn-bg);border-radius:9px;padding:9px 10px}\r\n.scroll{overflow:auto;max-width:100%}\r\n.panel-h{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:14px 18px;border-bottom:1px solid #E8EDEB}\r\n.panel-h h2{margin:0;font-size:17px}\r\n.pill{height:30px;padding:0 12px;border-radius:99px;border:1px solid var(--line);background:#F4F7F6;cursor:pointer;font-weight:600;font-size:12.5px}\r\n.pill[aria-pressed=\"true\"]{background:var(--btn);color:var(--btn-ink);border-color:var(--btn)}\r\n.sheet{width:100%;border-collapse:collapse;min-width:980px}\r\n.sheet th{font-size:12px;color:var(--muted);text-align:right;padding:10px 10px;border-bottom:1px solid var(--line);white-space:nowrap}\r\n.sheet th.l,.sheet td.dt{text-align:left}\r\n.sheet td{padding:6px 8px;border-bottom:1px solid #E8EDEB;vertical-align:middle}\r\n.sheet td.calc{background:#F4F7F6;text-align:right;white-space:nowrap;padding:0 10px;font-variant-numeric:tabular-nums}\r\n.sheet td.calc.nil{color:var(--muted);font-style:italic}\r\n.sheet tfoot td{position:sticky;bottom:0;background:var(--surface);border-top:2px solid var(--ink);font-weight:800;text-align:right;white-space:nowrap;padding:12px 10px}\r\n.sheet tfoot td.dt{text-align:left}\r\n.sheet td.dt{white-space:nowrap;font-weight:700}\r\n.sheet .dia1{display:inline-block;margin-left:6px;font-size:11px;font-weight:800;color:var(--ok);background:var(--ok-bg);border-radius:99px;padding:1px 8px}\r\n.foot-note{padding:12px 18px;color:var(--muted);font-size:12.5px}\r\n.d-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}\r\n.addday{display:flex;gap:8px;align-items:center;margin-left:auto}\r\n.in.sm{height:34px;width:auto}\r\n.btn.sm{height:32px;padding:0 10px;font-size:13px}\r\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:16px}\r\n.kpi{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:12px 14px}\r\n.kpi .lbl{font-size:12px;color:var(--muted);font-weight:700}\r\n.kpi .big{font-size:20px;font-weight:800;font-variant-numeric:tabular-nums}\r\n.kpi .big.good{color:var(--good)}.kpi .big.bad{color:var(--bad)}\r\n.kpi .sub2{font-size:12px;color:var(--muted)}\r\n.dl{font-size:12px;font-weight:800}.dl.g{color:var(--good)}.dl.b{color:var(--bad)}.dl.n{color:var(--muted)}\r\n.chart{width:100%;height:220px;display:block}\r\n.dd{position:relative}\r\n.dd-menu{display:none;position:absolute;top:42px;left:0;z-index:20;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:8px;min-width:220px;box-shadow:0 8px 24px rgba(0,0,0,.12)}\r\n.dd.open .dd-menu{display:block}\r\n.dd-item{display:block;width:100%;text-align:left;border:0;background:transparent;padding:8px 10px;border-radius:8px;cursor:pointer}\r\n.dd-item:hover{background:#F4F7F6}.dd-item.on{font-weight:800;background:#F4F7F6}\r\n.dd-list{max-height:220px;overflow:auto;display:grid;gap:2px;margin:6px 0}\r\n.dd-opt{display:flex;gap:8px;align-items:center;padding:6px 8px;border-radius:8px;font-size:13px}\r\n.dd-opt small{color:var(--muted);margin-left:auto}\r\n.lnk{border:0;background:transparent;color:var(--ok);font-weight:700;cursor:pointer}\r\nth[data-sort]{cursor:pointer;user-select:none}.ar{margin-left:4px}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"app\">\r\n  <aside class=\"side\">\r\n    <div class=\"brand\">Gestor de Tráfego</div>\r\n    <nav class=\"nav\" aria-label=\"Principal\">\r\n      <a href=\"#/dashboard\" data-nav=\"dashboard\">Dashboard</a>\r\n      <a href=\"#/criativos\" data-nav=\"criativos\">Criativos</a>\r\n      <a href=\"#/cadastro\" data-nav=\"cadastro\">Cadastro</a>\r\n      <a href=\"#/lancamento\" data-nav=\"lancamento\">Lançamento</a>\r\n      <a href=\"#/config\" data-nav=\"config\">Config</a>\r\n    </nav>\r\n  </aside>\r\n  <main class=\"main\"><div class=\"wrap\" id=\"view\"></div></main>\r\n</div>\r\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\r\n<script type=\"module\">\r\nimport * as Calc from \"/shared/calc.js\";\r\n\r\nconst $ = (s, r = document) => r.querySelector(s);\r\nconst $$ = (s, r = document) => Array.from(r.querySelectorAll(s));\r\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\r\nconst view = () => $(\"#view\");\r\nconst toast = (m) => { const t = $(\"#toast\"); t.textContent = m; t.classList.add(\"on\"); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove(\"on\"), 2600); };\r\nconst fDate = (s) => { const [y, m, d] = String(s).split(\"-\"); return `${d}/${m}/${y.slice(2)}`; };\r\nconst todayLocal = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,\"0\")}-${String(d.getDate()).padStart(2,\"0\")}`; };\r\n// Usa o módulo único de cálculo servido pelo servidor (ao-vivo + formato BR).\r\nconst fBRL = (cents) => Calc.formatBRL(cents);\r\n\r\nconst FORMAT = { video: \"Vídeo\", image: \"Imagem\", carousel: \"Carrossel\" };\r\nconst STATUS = { ativo: \"Ativo\", escalando: \"Escalando\", pausado: \"Pausado\", encerrado: \"Encerrado\" };\r\n\r\nfunction chipFor(h) {\r\n  const map = { \"Saudável\": \"ok\", \"Atenção\": \"warn\", \"Escalando\": \"good\", \"Pausado\": \"bad\", \"Encerrado\": \"bad\", \"Sem dados\": \"wait\" };\r\n  return `<span class=\"chip ${map[h.statusDisplay] ?? \"wait\"}\">${esc(h.statusDisplay)}</span>`;\r\n}\r\nfunction rulerFor(h) {\r\n  const pos = { vermelho: 12, amarelo: 37, azul: 62, verde: 87 };\r\n  if (h.ruler === \"cinza\") return `<span class=\"ruler off\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span>`;\r\n  return `<span class=\"ruler\" role=\"img\" aria-label=\"Saúde ${esc(h.statusDisplay)}\"><i></i><i></i><i></i><i></i><b style=\"left:${pos[h.ruler] ?? 62}%\"></b></span>`;\r\n}\r\nconst profitClass = (cents) => cents == null ? \"\" : cents >= 0 ? \"good\" : \"bad\";\r\nasync function api(path, opts) {\r\n  const res = await fetch(path, opts);\r\n  const body = await res.json().catch(() => ({}));\r\n  if (!res.ok) { const e = new Error(body.error || \"erro\"); e.status = res.status; e.body = body; throw e; }\r\n  return body;\r\n}\r\n\r\n// ---------- Biblioteca (T5: busca + status + ordenação lucro/ROAS/custo/vendas) ----------\r\nconst L = { q: \"\", status: \"all\", sort: \"recent\" };\r\nconst fRoas = (n) => Calc.formatRoas(n);\r\nasync function pageLibrary() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Criativos</h1><p class=\"sub\" id=\"lib-sub\">Biblioteca — busque, filtre e compare</p></div><a class=\"btn\" href=\"#/cadastro\">+ Cadastrar criativo</a></div>\r\n  <div class=\"fb\">\r\n    <label class=\"ctl search\"><input id=\"lib-q\" placeholder=\"Buscar por nome ou produto\" value=\"${esc(L.q)}\" aria-label=\"Buscar criativo\"></label>\r\n    <label class=\"ctl\">Status <select id=\"lib-status\"><option value=\"all\">Todos</option>${Object.entries(STATUS).map(([k,v]) => `<option value=\"${k}\">${v}</option>`).join(\"\")}</select></label>\r\n    <label class=\"ctl\">Ordenar <select id=\"lib-sort\"><option value=\"recent\">Mais recentes</option><option value=\"name\">Nome A–Z</option><option value=\"profit\">Maior lucro</option><option value=\"roas\">Maior ROAS-equiv.</option><option value=\"cost\">Maior custo</option><option value=\"sales\">Mais vendas</option></select></label>\r\n  </div>\r\n  <section class=\"panel\"><div class=\"panel-b\" id=\"lib-body\">Carregando…</div></section>`;\r\n  $(\"#lib-status\").value = L.status; $(\"#lib-sort\").value = L.sort;\r\n  $(\"#lib-q\").addEventListener(\"input\", (e) => { L.q = e.target.value; libBody(); });\r\n  $(\"#lib-status\").addEventListener(\"change\", (e) => { L.status = e.target.value; libBody(); });\r\n  $(\"#lib-sort\").addEventListener(\"change\", (e) => { L.sort = e.target.value; libBody(); });\r\n  $(\"#lib-body\").addEventListener(\"click\", (e) => { const tr = e.target.closest(\"tr[data-id]\"); if (tr) location.hash = \"#/criativo/\" + tr.dataset.id; });\r\n  await libBody();\r\n}\r\nasync function libBody() {\r\n  const box = $(\"#lib-body\");\r\n  try {\r\n    const qs = new URLSearchParams();\r\n    if (L.q.trim()) qs.set(\"q\", L.q.trim());\r\n    if (L.status !== \"all\") qs.set(\"status\", L.status);\r\n    // Ordenação no servidor (contrato ?sort=profit|roas|cost|sales|name|recent).\r\n    if (L.sort && L.sort !== \"recent\") qs.set(\"sort\", L.sort);\r\n    const { data } = await api(\"/api/creatives?\" + qs.toString());\r\n    const rows = [...data];\r\n    $(\"#lib-sub\").textContent = `${rows.length} criativo(s) na biblioteca`;\r\n    if (!rows.length) { box.innerHTML = `<div class=\"empty\"><strong>Nenhum criativo encontrado</strong><span>Tente outra busca ou cadastre um novo.</span><a class=\"btn\" href=\"#/cadastro\">Cadastrar criativo</a></div>`; return; }\r\n    box.innerHTML = `<div style=\"overflow:auto\"><table class=\"tbl\"><thead><tr><th>Criativo</th><th>Status</th><th class=\"num\">Custo</th><th class=\"num\">Vendas</th><th class=\"num\">ROAS-equiv.</th><th class=\"num\">Lucro</th><th>Saúde do dia</th><th>Motivo</th></tr></thead><tbody>${rows.map((c) => {\r\n      const pc = profitClass(c.totals.profit_cents);\r\n      const roas = c.totals.roas_equivalente;\r\n      return `<tr class=\"click\" data-id=\"${c.id}\"><td><div class=\"nm\">${esc(c.name)}</div><div class=\"sub\">${esc(c.product || \"—\")} · ${FORMAT[c.format] ?? c.format} · ${fDate(c.start_date)}</div></td><td>${chipFor(c.health)}</td><td class=\"num\">${fBRL(c.totals.cost_cents)}</td><td class=\"num\">${c.totals.sales}</td><td class=\"num\">${roas == null ? \"—\" : fRoas(roas)}</td><td class=\"num prof ${pc}\">${c.totals.profit_cents == null ? (c.totals.has_pending ? \"pendente\" : \"—\") : fBRL(c.totals.profit_cents)}</td><td>${rulerFor(c.health)}</td><td class=\"mut\">${esc(c.health.motivo ?? \"—\")}</td></tr>`;\r\n    }).join(\"\")}</tbody></table></div><div class=\"foot-note\">ROAS-equiv. = faturamento ÷ custo c/ imposto (só comparação — a cor vem do Sinal). Lucro “pendente” = vendeu e o faturamento ainda não foi lançado.</div>`;\r\n  } catch { box.innerHTML = `<div class=\"empty\"><strong>Não foi possível carregar</strong></div>`; }\r\n}\r\n\r\n// ---------- Cadastro (T2 único + T3 em lote) ----------\r\n// produto/formato/data mantidos após cada cadastro para encadear o próximo.\r\nconst R = { mode: \"single\", name: \"\", bulk: \"\", product: \"\", format: \"video\", start: todayLocal(), status: \"ativo\", url: \"\", notes: \"\" };\r\nconst bulkNames = () => R.bulk.split(\"\\n\").map((s) => s.trim()).filter(Boolean);\r\nasync function pageRegister() {\r\n  let products = [];\r\n  let existing = [];\r\n  try { const { data } = await api(\"/api/creatives\"); products = [...new Set(data.map((c) => c.product).filter(Boolean))].sort((a,b)=>a.localeCompare(b,\"pt-BR\")); existing = data.map((c) => ({ name: c.name, status: c.status })); } catch {}\r\n  const bulk = R.mode === \"bulk\";\r\n  const isFuture = R.start > todayLocal();\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Cadastro</h1><p class=\"sub\">Registre os criativos novos. Os números do dia entram depois, no lançamento.</p></div></div>\r\n  <div class=\"cols\">\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <div class=\"seg\" role=\"group\" aria-label=\"Modo de cadastro\"><button type=\"button\" data-mode=\"single\" aria-pressed=\"${!bulk}\">Um criativo</button><button type=\"button\" data-mode=\"bulk\" aria-pressed=\"${bulk}\">Vários de uma vez</button></div>\r\n    <div style=\"height:14px\"></div>\r\n    ${bulk\r\n      ? `<div class=\"fld\"><label for=\"r-bulk\">Nomes dos criativos (um por linha)</label><textarea class=\"in\" id=\"r-bulk\" rows=\"6\" placeholder=\"Depoimento cozinha 03&#10;UGC achadinho 04\">${esc(R.bulk)}</textarea><div class=\"bulkprev\" id=\"r-prev\" aria-live=\"polite\"></div><div class=\"err-msg\" id=\"r-err\" hidden></div></div>`\r\n      : `<div class=\"fld\"><label for=\"r-name\">Nome do criativo</label><input class=\"in\" id=\"r-name\" value=\"${esc(R.name)}\" placeholder=\"Ex.: Depoimento cozinha 03\" autocomplete=\"off\"><div class=\"err-msg\" id=\"r-err\" hidden></div></div>`}\r\n    <div class=\"fld\"><label for=\"r-product\">Produto ou oferta</label><input class=\"in\" id=\"r-product\" list=\"r-products\" value=\"${esc(R.product)}\" placeholder=\"Ex.: Mini processador\" autocomplete=\"off\"><datalist id=\"r-products\">${products.map((p)=>`<option value=\"${esc(p)}\">`).join(\"\")}</datalist><span class=\"hint\">Mantido após cadastrar para encadear o próximo.</span></div>\r\n    <div class=\"fld\"><span class=\"l\" style=\"font-weight:700\">Formato</span><div class=\"seg\" role=\"group\" aria-label=\"Formato\">${Object.entries(FORMAT).map(([k,v])=>`<button type=\"button\" data-format=\"${k}\" aria-pressed=\"${R.format===k}\">${v}</button>`).join(\"\")}</div></div>\r\n    <div class=\"two\">\r\n      <div class=\"fld\"><label for=\"r-start\">Data de início</label><input type=\"date\" class=\"in\" id=\"r-start\" value=\"${esc(R.start)}\"><span class=\"hint\">Mantida após cadastrar.</span></div>\r\n      <div class=\"fld\"><label for=\"r-status\">Status inicial</label><select class=\"in\" id=\"r-status\">${Object.entries(STATUS).map(([k,v])=>`<option value=\"${k}\">${v}</option>`).join(\"\")}</select></div>\r\n    </div>\r\n    ${isFuture ? `<p class=\"hint\" id=\"r-pre\">Pré-cadastro: começa em ${fDate(R.start)} — não conta Dia 1 nem dispara Sinal até ter movimento.</p>` : ``}\r\n    ${bulk ? `` : `\r\n    <div class=\"fld\"><label for=\"r-url\">Link do Criativo (opcional)</label><input class=\"in\" id=\"r-url\" type=\"url\" value=\"${esc(R.url)}\" placeholder=\"Pasta do Drive ou link do Criativo\"></div>\r\n    <div class=\"fld\"><label for=\"r-notes\">Observações (opcional)</label><textarea class=\"in\" id=\"r-notes\" placeholder=\"Gancho, ângulo, público…\">${esc(R.notes)}</textarea></div>`}\r\n    <div class=\"actions\"><button class=\"btn\" id=\"r-save\" type=\"button\"><span id=\"r-save-l\">Cadastrar</span></button><button class=\"btn ghost\" id=\"r-save-go\" type=\"button\">Cadastrar e lançar dados</button></div>\r\n  </div></section>\r\n  <section class=\"panel\"><div class=\"panel-b\"><strong>Últimos cadastrados</strong></div><ul class=\"recent\" id=\"r-recent\"><li class=\"mut\">Carregando…</li></ul></section>\r\n  </div>`;\r\n  $(\"#r-status\").value = R.status;\r\n  const errEl = () => $(\"#r-err\");\r\n  const showErr = (m, sel) => { const e = errEl(); e.textContent = m; e.hidden = false; const i = sel ? $(sel) : null; if (i) { i.classList.add(\"err\"); i.focus(); } };\r\n  const clearErr = () => { const e = errEl(); if (e) e.hidden = true; $$(\".in.err\").forEach((i)=>i.classList.remove(\"err\")); };\r\n  const paintPreview = () => {\r\n    const box = $(\"#r-prev\");\r\n    if (!box) { const l = $(\"#r-save-l\"); if (l) l.textContent = \"Cadastrar\"; return; }\r\n    const names = bulkNames();\r\n    const taken = new Set(existing.filter((c) => c.status !== \"encerrado\").map((c) => String(c.name).toLowerCase()));\r\n    const seen = new Set();\r\n    box.innerHTML = names.map((n) => {\r\n      const k = n.toLowerCase();\r\n      const dup = taken.has(k) || seen.has(k);\r\n      seen.add(k);\r\n      return `<span class=\"${dup ? \"dup\" : \"\"}\">${esc(n)}</span>`;\r\n    }).join(\"\");\r\n    $(\"#r-save-l\").textContent = names.length > 1 ? `Cadastrar ${names.length} criativos` : \"Cadastrar\";\r\n  };\r\n  $$(\"[data-mode]\").forEach((b) => b.addEventListener(\"click\", () => { R.mode = b.dataset.mode; pageRegister(); }));\r\n  const nameInput = $(\"#r-name\");\r\n  if (nameInput) nameInput.addEventListener(\"input\", (e) => { R.name = e.target.value; clearErr(); });\r\n  const bulkInput = $(\"#r-bulk\");\r\n  if (bulkInput) bulkInput.addEventListener(\"input\", (e) => { R.bulk = e.target.value; clearErr(); paintPreview(); });\r\n  $(\"#r-product\").addEventListener(\"input\", (e) => { R.product = e.target.value; });\r\n  $(\"#r-start\").addEventListener(\"change\", (e) => { R.start = e.target.value || todayLocal(); pageRegister(); });\r\n  $(\"#r-status\").addEventListener(\"change\", (e) => { R.status = e.target.value; });\r\n  const urlInput = $(\"#r-url\");\r\n  if (urlInput) urlInput.addEventListener(\"input\", (e) => { R.url = e.target.value; });\r\n  const notesInput = $(\"#r-notes\");\r\n  if (notesInput) notesInput.addEventListener(\"input\", (e) => { R.notes = e.target.value; });\r\n  $$(\"[data-format]\").forEach((b) => b.addEventListener(\"click\", () => { R.format = b.dataset.format; $$(\"[data-format]\").forEach((x)=>x.setAttribute(\"aria-pressed\", x===b)); }));\r\n  $(\"#r-save\").addEventListener(\"click\", () => submitRegister(false, showErr));\r\n  $(\"#r-save-go\").addEventListener(\"click\", () => submitRegister(true, showErr));\r\n  paintPreview();\r\n  await paintRecent();\r\n}\r\nasync function paintRecent() {\r\n  try {\r\n    const { data } = await api(\"/api/creatives\");\r\n    const last = [...data].sort((a,b)=>b.id-a.id).slice(0,6);\r\n    $(\"#r-recent\").innerHTML = last.length ? last.map((c)=>`<li><div><a href=\"#/criativo/${c.id}\">${esc(c.name)}</a><div class=\"sub\">${esc(c.product||\"—\")} · ${FORMAT[c.format]} · ${fDate(c.start_date)}</div></div>${chipFor(c.health)}</li>`).join(\"\") : `<li class=\"mut\">Nenhum criativo ainda.</li>`;\r\n  } catch { const el = $(\"#r-recent\"); if (el) el.innerHTML = `<li class=\"mut\">—</li>`; }\r\n}\r\nasync function submitRegister(goDaily, err) {\r\n  if (R.mode === \"bulk\") {\r\n    const names = bulkNames();\r\n    if (!names.length) { err(\"Digite pelo menos um nome, um por linha.\", \"#r-bulk\"); return; }\r\n    try {\r\n      const { data } = await api(\"/api/creatives/bulk\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ names, product: R.product.trim(), format: R.format, start_date: R.start, status: R.status }) });\r\n      // Mantém produto/formato/data para encadear; limpa só a lista.\r\n      R.bulk = \"\";\r\n      toast(data.length === 1 ? `Criativo cadastrado: ${data[0].name}` : `${data.length} criativos cadastrados`);\r\n      if (goDaily) { location.hash = \"#/lancamento\"; } else { pageRegister(); const f = $(\"#r-bulk\"); if (f) f.focus(); }\r\n    } catch (e) {\r\n      const warns = e.body?.warnings ?? [];\r\n      if (e.body?.error === \"nome_duplicado\") err(warns[0] || \"Há nomes repetidos ou já cadastrados (em vermelho).\", \"#r-bulk\");\r\n      else err(\"Não foi possível cadastrar. Confira os campos.\", \"#r-bulk\");\r\n    }\r\n    return;\r\n  }\r\n  const payload = { name: R.name.trim(), product: R.product.trim(), format: R.format, start_date: R.start, status: R.status, url: R.url.trim(), notes: R.notes };\r\n  if (!payload.name) { err(\"Informe o nome do criativo.\", \"#r-name\"); return; }\r\n  try {\r\n    const { data } = await api(\"/api/creatives\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify(payload) });\r\n    // Mantém produto/formato/data para encadear; limpa só nome/link/observações.\r\n    R.name = \"\"; R.url = \"\"; R.notes = \"\";\r\n    toast(`Criativo cadastrado: ${data.name}`);\r\n    if (goDaily) { location.hash = \"#/lancamento\"; } else { pageRegister(); const f = $(\"#r-name\"); if (f) f.focus(); }\r\n  } catch (e) {\r\n    const warns = e.body?.warnings ?? [];\r\n    if (e.body?.error === \"nome_duplicado\") err(warns[0] || \"Já existe um criativo com esse nome.\", \"#r-name\");\r\n    else err(\"Não foi possível cadastrar. Confira os campos.\", \"#r-name\");\r\n  }\r\n}\r\n\r\n// ---------- Detalhe réplica-da-planilha (T4) ----------\r\n// Colunas digitáveis (brancas): Investimento, Vendas, Faturamento, Cliques Meta/Shopee.\r\n// Colunas calculadas (cinza, via Calc): Custo, Lucro, CPCs. TOTAL fixo no rodapé = agg().\r\n// Filtro por mês, adicionar dia (upsert por data), ciclo de vida + régua/Status/Motivo.\r\nconst DT = { id: null, month: \"all\", creative: null, entries: [], months: [], dia1: null, health: null };\r\nconst monthLabel = (m) => { const [y, mo] = m.split(\"-\"); return `${mo}/${y.slice(2)}`; };\r\nasync function pageDetail(id) {\r\n  DT.id = id; DT.month = \"all\"; DT.creative = null; DT.entries = [];\r\n  view().innerHTML = `<div class=\"panel-b mut\">Carregando…</div>`;\r\n  try {\r\n    await loadDetail();\r\n  } catch { location.hash = \"#/criativos\"; }\r\n}\r\nasync function loadDetail() {\r\n  const id = DT.id;\r\n  const qs = DT.month !== \"all\" ? \"?month=\" + encodeURIComponent(DT.month) : \"\";\r\n  const [{ data: c }, det] = await Promise.all([\r\n    api(\"/api/creatives/\" + id),\r\n    api(\"/api/creatives/\" + id + \"/entries\" + qs),\r\n  ]);\r\n  DT.creative = det.data.creative;\r\n  DT.entries = det.data.entries;\r\n  DT.months = det.data.months;\r\n  DT.dia1 = det.data.dia1;\r\n  DT.health = det.data.health;\r\n  renderDetail(c.data, det);\r\n}\r\nfunction renderDetail(c, det) {\r\n  const h = det.data.health;\r\n  const pc = profitClass(det.data.totals.profit_cents);\r\n  const encerrado = DT.creative.status === \"encerrado\";\r\n  const st = DT.creative.status;\r\n  const actions =\r\n    st === \"ativo\" ? `<button class=\"btn ghost sm\" data-act=\"escalando\" type=\"button\">Escalar</button><button class=\"btn ghost sm\" data-act=\"pausado\" type=\"button\">Pausar</button><button class=\"btn ghost sm\" data-act=\"encerrado\" type=\"button\">Encerrar</button>`\r\n    : st === \"escalando\" ? `<button class=\"btn ghost sm\" data-act=\"ativo\" type=\"button\">Desmarcar escala</button><button class=\"btn ghost sm\" data-act=\"pausado\" type=\"button\">Pausar</button><button class=\"btn ghost sm\" data-act=\"encerrado\" type=\"button\">Encerrar</button>`\r\n    : st === \"pausado\" ? `<button class=\"btn sm\" data-act=\"ativo\" type=\"button\">Reabrir</button><button class=\"btn ghost sm\" data-act=\"encerrado\" type=\"button\">Encerrar</button>`\r\n    : `<button class=\"btn sm\" data-act=\"ativo\" type=\"button\">Reabrir</button>`;\r\n  const t = det.data.totals;\r\n  const profitLabel = t.profit_cents == null ? (t.has_pending ? \"pendente\" : \"—\") : fBRL(t.profit_cents);\r\n  view().innerHTML = `\r\n  <a href=\"#/criativos\" style=\"color:var(--muted);text-decoration:none\">← Criativos</a>\r\n  <div class=\"ph\"><div><h1>${esc(DT.creative.name)}</h1><p class=\"sub\">${esc(DT.creative.product || \"—\")} · ${FORMAT[DT.creative.format]} · início em ${fDate(DT.creative.start_date)}</p></div><div class=\"d-actions\">${chipFor(h)}${actions}</div></div>\r\n  <section class=\"panel\"><div class=\"panel-b\" style=\"display:flex;gap:24px;flex-wrap:wrap;align-items:center\">${rulerFor(h)}<span><strong class=\"prof ${pc}\">${esc(profitLabel)}</strong> <span class=\"mut\">lucro · ${fBRL(t.investment_cents)} investidos · ${t.sales} vendas</span></span><span class=\"mut\">${esc(h.motivo ?? (h.dia1 ? \"—\" : \"Pré-cadastro: sem Dia 1, sem Sinal até ter movimento.\"))}</span></div>\r\n  ${det.warnings?.length ? `<div class=\"warnbox\">${esc(det.warnings.join(\" \"))}</div>` : ``}</section>\r\n  <section class=\"panel\">\r\n    <div class=\"panel-h\"><h2>Lançamentos diários</h2><div id=\"d-months\" style=\"display:flex;gap:6px;flex-wrap:wrap\">${[[\"all\", \"Tudo\"], ...DT.months.map((m) => [m, monthLabel(m)])].map(([k, l]) => `<button type=\"button\" class=\"pill\" data-m=\"${k}\" aria-pressed=\"${DT.month === k}\">${l}</button>`).join(\"\")}</div>\r\n    <div class=\"addday\"><input type=\"date\" class=\"in sm\" id=\"add-date\" aria-label=\"Data do novo lançamento\" ${encerrado ? \"disabled\" : \"\"}><button class=\"btn sm\" id=\"add-btn\" type=\"button\" ${encerrado ? \"disabled\" : \"\"}>+ Adicionar dia</button></div></div>\r\n    <div class=\"scroll\" id=\"sheetbox\"></div>\r\n    <div class=\"foot-note\">Colunas em cinza são calculadas (Custo = investimento × (1 + imposto) · Lucro = faturamento − custo · CPC = investimento ÷ cliques). Deixe o faturamento vazio até a comissão ser confirmada: o dia fica pendente, fora do lucro. Valores em R$. ${encerrado ? \"Encerrado: histórico, sem lançamentos — reabra para lançar.\" : \"\"}</div>\r\n  </section>`;\r\n  $(\"#d-months\").addEventListener(\"click\", (e) => {\r\n    const b = e.target.closest(\"[data-m]\");\r\n    if (!b) return;\r\n    DT.month = b.dataset.m;\r\n    loadDetail();\r\n  });\r\n  view().querySelector(\".d-actions\").addEventListener(\"click\", async (e) => {\r\n    const b = e.target.closest(\"[data-act]\");\r\n    if (!b) return;\r\n    try {\r\n      await api(\"/api/creatives/\" + DT.id, { method: \"PATCH\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ status: b.dataset.act }) });\r\n      toast(b.dataset.act === \"escalando\" ? \"Marcado como Escalando\" : b.dataset.act === \"ativo\" ? (st === \"encerrado\" || st === \"pausado\" ? \"Criativo reaberto\" : \"Escala desmarcada\") : b.dataset.act === \"pausado\" ? \"Criativo pausado — ainda recebe vendas (cookie)\" : \"Criativo encerrado — fica no histórico\");\r\n      await loadDetail();\r\n    } catch (err) {\r\n      toast(err.body?.error === \"escalando_so_do_ativo\" ? \"Só criativos Ativos podem ser Escalando.\" : \"Não foi possível atualizar o status.\");\r\n    }\r\n  });\r\n  const last = DT.entries.length ? DT.entries[0].date : DT.creative.start_date;\r\n  const addInput = $(\"#add-date\");\r\n  if (addInput && !encerrado) {\r\n    addInput.value = last;\r\n    addInput.max = todayLocal();\r\n    $(\"#add-btn\").addEventListener(\"click\", async () => {\r\n      const d = addInput.value;\r\n      if (!d) return;\r\n      if (DT.entries.some((e) => e.date === d)) {\r\n        const tr = view().querySelector(`tr[data-date=\"${d}\"]`);\r\n        if (tr) { tr.scrollIntoView({ block: \"nearest\" }); const i = tr.querySelector(\"input\"); if (i) i.focus(); }\r\n        return;\r\n      }\r\n      try {\r\n        await api(`/api/creatives/${DT.id}/entries/${d}`, { method: \"PUT\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ investment_cents: 0, sales: 0, revenue_cents: null, clicks_meta: 0, clicks_shopee: 0 }) });\r\n        if (DT.month !== \"all\") DT.month = d.slice(0, 7);\r\n        toast(`Dia ${fDate(d)} adicionado`);\r\n        await loadDetail();\r\n      } catch (err) {\r\n        toast(err.body?.error === \"encerrado_sem_lancamento\" ? \"Criativo encerrado não recebe lançamentos.\" : \"Não foi possível adicionar o dia.\");\r\n      }\r\n    });\r\n  }\r\n  renderSheet();\r\n  const box = $(\"#sheetbox\");\r\n  box.addEventListener(\"input\", (ev) => {\r\n    const inp = ev.target.closest(\"input[data-f]\");\r\n    if (!inp) return;\r\n    paintDetailRow(inp.closest(\"tr\"));\r\n    paintDetailTotals();\r\n  });\r\n  box.addEventListener(\"keydown\", (ev) => {\r\n    if (ev.key !== \"Enter\" || !ev.target.matches(\"input[data-f]\")) return;\r\n    ev.preventDefault();\r\n    ev.target.blur();\r\n  });\r\n  box.addEventListener(\"focusout\", async (ev) => {\r\n    const inp = ev.target.closest(\"input[data-f]\");\r\n    if (!inp) return;\r\n    const tr = inp.closest(\"tr\");\r\n    if (inp.classList.contains(\"bad\")) return;\r\n    await saveDetailRow(tr);\r\n  });\r\n}\r\nfunction detailEntryFromRow(tr) {\r\n  const tax = Number(tr.dataset.tax || 0.1386);\r\n  const date = tr.dataset.date;\r\n  const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\r\n  const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\r\n  const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\r\n  const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\r\n  const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\r\n  return { tax, date, inv, rev, sales, clM, clS };\r\n}\r\nfunction paintDetailRow(tr) {\r\n  const { tax, date, inv, rev, sales, clM, clS } = detailEntryFromRow(tr);\r\n  const bad =\r\n    [inv, sales, clM, clS].some((v) => typeof v === \"number\" && Number.isNaN(v)) ||\r\n    (rev != null && Number.isNaN(rev));\r\n  [\"invest\", \"sales\", \"rev\", \"clM\", \"clS\"].forEach((f) => $('[data-f=\"' + f + '\"]', tr).classList.remove(\"bad\"));\r\n  if (bad) return;\r\n  const invC = inv == null ? 0 : inv;\r\n  const salesN = sales == null ? 0 : sales;\r\n  const clMN = clM == null ? 0 : clM;\r\n  const clSN = clS == null ? 0 : clS;\r\n  const row = Calc.calcRow({ date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax });\r\n  $('[data-c=\"cost\"]', tr).textContent = Calc.formatBRL(row.cost_cents);\r\n  const pEl = $('[data-c=\"profit\"]', tr);\r\n  pEl.textContent = row.is_pending ? \"pendente\" : Calc.formatBRL(row.profit_cents);\r\n  pEl.className = \"calc\" + (row.profit_cents == null || row.is_pending ? \" nil\" : row.profit_cents >= 0 ? \" prof good\" : \" prof bad\");\r\n  $('[data-c=\"cpcM\"]', tr).textContent = Calc.formatCPC(row.cpc_meta_cents);\r\n  $('[data-c=\"cpcS\"]', tr).textContent = Calc.formatCPC(row.cpc_shopee_cents);\r\n  const hEl = $('[data-c=\"health\"]', tr);\r\n  const dayForSignal = { date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax };\r\n  // Módulo único: dia sem movimento nunca tem sinal (igual ao servidor).\r\n  if (!Calc.hasMovement(dayForSignal)) { hEl.textContent = \"—\"; return; }\r\n  try {\r\n    // Ao-vivo: data anterior ao Dia 1 salvo vira o novo Dia 1 após salvar (<=);\r\n    // sem Dia 1 salvo, o primeiro dia com movimento é o Dia 1.\r\n    const isDia1 = !DT.dia1 || date <= DT.dia1;\r\n    const sig = Calc.evaluateDay(dayForSignal, isDia1);\r\n    hEl.textContent = sig.saude === \"atencao\" ? `Atenção · ${sig.motivo ?? \"\"}` : (sig.motivo ?? \"Saudável\");\r\n  } catch { hEl.textContent = \"—\"; }\r\n}\r\nfunction paintDetailTotals() {\r\n  const rows = $$(\"#sheetbox tr[data-date]\");\r\n  const days = [];\r\n  for (const tr of rows) {\r\n    const { tax, date, inv, rev, sales, clM, clS } = detailEntryFromRow(tr);\r\n    if ([inv, sales, clM, clS].some((v) => typeof v === \"number\" && Number.isNaN(v))) continue;\r\n    days.push({ date, investment_cents: inv ?? 0, sales: sales ?? 0, revenue_cents: rev, clicks_meta: clM ?? 0, clicks_shopee: clS ?? 0, tax_rate: tax });\r\n  }\r\n  const a = Calc.agg(days);\r\n  const set = (k, txt, cls) => { const td = view().querySelector(`[data-t=\"${k}\"]`); if (td) { td.textContent = txt; if (cls) td.className = cls; } };\r\n  set(\"invest\", Calc.formatBRL(a.investment_cents));\r\n  set(\"cost\", Calc.formatBRL(a.cost_cents));\r\n  set(\"sales\", String(a.sales));\r\n  set(\"rev\", a.costClosed_cents > 0 || a.revenue_cents > 0 ? Calc.formatBRL(a.revenue_cents) : \"—\");\r\n  set(\"profit\", a.profit_cents == null ? (a.has_pending ? \"pendente\" : \"—\") : Calc.formatBRL(a.profit_cents));\r\n  set(\"clM\", String(a.clicks_meta));\r\n  set(\"clS\", String(a.clicks_shopee));\r\n  set(\"cpcM\", Calc.formatCPC(a.cpc_meta_cents));\r\n  set(\"cpcS\", Calc.formatCPC(a.cpc_shopee_cents));\r\n}\r\nfunction renderSheet() {\r\n  const box = $(\"#sheetbox\");\r\n  const encerrado = DT.creative.status === \"encerrado\";\r\n  if (!DT.entries.length) {\r\n    box.innerHTML = `<div class=\"empty\"><strong>Nenhum lançamento${DT.month !== \"all\" ? \" neste mês\" : \" ainda\"}</strong><span>${encerrado ? \"Criativo encerrado: histórico, sem lançamentos.\" : \"Adicione o primeiro dia acima ou lance pelo Lançamento diário.\"}</span></div>`;\r\n    return;\r\n  }\r\n  box.innerHTML = `<table class=\"sheet\"><thead><tr><th class=\"l\">Data</th><th>Investimento</th><th>Custo c/ imposto</th><th>Vendas</th><th>Faturamento</th><th>Lucro</th><th>Cliques Meta</th><th>Cliques Shopee</th><th>CPC Meta</th><th>CPC Shopee</th><th class=\"l\">Saúde do dia</th></tr></thead><tbody>${DT.entries.map((e) => {\r\n    const dis = encerrado ? \"disabled\" : \"\";\r\n    return `<tr data-date=\"${e.date}\" data-tax=\"${e.tax_rate}\"><td class=\"dt\">${fDate(e.date)}${e.is_dia1 ? `<span class=\"dia1\">Dia 1</span>` : ``}</td>`\r\n      + `<td><input class=\"ci\" data-f=\"invest\" inputmode=\"decimal\" value=\"${esc(e.investment_cents ? fmtInputCents(e.investment_cents) : \"\")}\" placeholder=\"0,00\" ${dis}></td>`\r\n      + `<td class=\"calc\" data-c=\"cost\">—</td>`\r\n      + `<td><input class=\"ci\" data-f=\"sales\" inputmode=\"numeric\" value=\"${esc(e.sales ? String(e.sales) : \"\")}\" placeholder=\"0\" ${dis}></td>`\r\n      + `<td><input class=\"ci\" data-f=\"rev\" inputmode=\"decimal\" value=\"${esc(e.revenue_cents != null ? fmtInputCents(e.revenue_cents) : \"\")}\" placeholder=\"pendente\" ${dis}></td>`\r\n      + `<td class=\"calc\" data-c=\"profit\">—</td>`\r\n      + `<td><input class=\"ci\" data-f=\"clM\" inputmode=\"numeric\" value=\"${esc(e.clicks_meta ? String(e.clicks_meta) : \"\")}\" placeholder=\"0\" ${dis}></td>`\r\n      + `<td><input class=\"ci\" data-f=\"clS\" inputmode=\"numeric\" value=\"${esc(e.clicks_shopee ? String(e.clicks_shopee) : \"\")}\" placeholder=\"0\" ${dis}></td>`\r\n      + `<td class=\"calc\" data-c=\"cpcM\">—</td><td class=\"calc\" data-c=\"cpcS\">—</td>`\r\n      + `<td class=\"mut\" data-c=\"health\" style=\"white-space:normal;min-width:140px\">—</td></tr>`;\r\n  }).join(\"\")}</tbody><tfoot><tr><td class=\"dt\">TOTAL</td><td data-t=\"invest\"></td><td data-t=\"cost\"></td><td data-t=\"sales\"></td><td data-t=\"rev\"></td><td data-t=\"profit\"></td><td data-t=\"clM\"></td><td data-t=\"clS\"></td><td data-t=\"cpcM\"></td><td data-t=\"cpcS\"></td><td></td></tr></tfoot></table>`;\r\n  $$(\"#sheetbox tr[data-date]\").forEach(paintDetailRow);\r\n  paintDetailTotals();\r\n}\r\nasync function saveDetailRow(tr) {\r\n  const date = tr.dataset.date;\r\n  const { inv, rev, sales, clM, clS } = detailEntryFromRow(tr);\r\n  const name = DT.creative.name;\r\n  let bad = false;\r\n  const mark = (f) => { $('[data-f=\"' + f + '\"]', tr).classList.add(\"bad\"); bad = true; };\r\n  for (const [f, v] of [[\"invest\", inv], [\"sales\", sales], [\"rev\", rev], [\"clM\", clM], [\"clS\", clS]]) {\r\n    if (typeof v === \"number\" && Number.isNaN(v)) mark(f);\r\n    if (typeof v === \"number\" && v != null && v < 0) mark(f);\r\n  }\r\n  for (const [f, v] of [[\"sales\", sales], [\"clM\", clM], [\"clS\", clS]]) {\r\n    if (typeof v === \"number\" && v != null && !Number.isInteger(v)) mark(f);\r\n  }\r\n  if (bad) { toast(`Confira os números de ${name} em ${fDate(date)}.`); return; }\r\n  try {\r\n    await api(`/api/creatives/${DT.id}/entries/${date}`, { method: \"PUT\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ investment_cents: inv ?? 0, sales: sales ?? 0, revenue_cents: rev, clicks_meta: clM ?? 0, clicks_shopee: clS ?? 0 }) });\r\n    toast(`Dia ${fDate(date)} salvo`);\r\n    await loadDetail();\r\n  } catch (err) {\r\n    toast(err.body?.error === \"encerrado_sem_lancamento\" ? \"Criativo encerrado não recebe lançamentos.\" : \"Não foi possível salvar. Confira os números.\");\r\n  }\r\n}\r\n// ---------- Lançamento diário em lote (T3) ----------\r\n// Um dia, todos os Ativos numa tabela só. Tudo recalcula ao digitar via Calc.\r\nconst DY = { date: todayLocal() };\r\nconst fmtInputCents = (cents) => cents == null ? \"\" : (cents / 100).toLocaleString(\"pt-BR\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\r\nfunction pageDaily() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Lançamento diário</h1><p class=\"sub\">Lance o dia de todos os Ativos numa tabela só.</p></div><a class=\"btn ghost\" href=\"#/cadastro\">Cadastrar criativo</a></div>\r\n  <div class=\"daybar\">\r\n    <button class=\"btn ghost sm\" id=\"dy-prev\" type=\"button\" aria-label=\"Dia anterior\">←</button>\r\n    <input type=\"date\" class=\"in sm\" id=\"dy-date\" style=\"width:auto\" aria-label=\"Data do lançamento\">\r\n    <button class=\"btn ghost sm\" id=\"dy-next\" type=\"button\" aria-label=\"Próximo dia\">→</button>\r\n    <button class=\"btn ghost sm\" id=\"dy-today\" type=\"button\">Hoje</button>\r\n    <span class=\"long\" id=\"dy-long\"></span>\r\n  </div>\r\n  <section class=\"panel\"><div class=\"scroll\" id=\"dy-body\"><div class=\"panel-b mut\">Carregando…</div></div>\r\n    <div class=\"warnbox\" id=\"dy-warn\" hidden></div>\r\n    <div class=\"savebar\"><span id=\"dy-count\" class=\"mut\"></span><button class=\"btn\" id=\"dy-save\" type=\"button\">Salvar lançamentos</button></div></section>`;\r\n  const go = (d) => { if (!d || d > todayLocal()) return; DY.date = d; renderDay(); };\r\n  $(\"#dy-date\").max = todayLocal();\r\n  $(\"#dy-prev\").addEventListener(\"click\", () => {\r\n    const [y, m, d] = DY.date.split(\"-\").map(Number);\r\n    const dt = new Date(Date.UTC(y, m - 1, d - 1));\r\n    go(dt.toISOString().slice(0, 10));\r\n  });\r\n  $(\"#dy-next\").addEventListener(\"click\", () => {\r\n    const [y, m, d] = DY.date.split(\"-\").map(Number);\r\n    const dt = new Date(Date.UTC(y, m - 1, d + 1));\r\n    const iso = dt.toISOString().slice(0, 10);\r\n    if (iso <= todayLocal()) go(iso);\r\n  });\r\n  $(\"#dy-today\").addEventListener(\"click\", () => go(todayLocal()));\r\n  $(\"#dy-date\").addEventListener(\"change\", (e) => go(e.target.value));\r\n  $(\"#dy-save\").addEventListener(\"click\", saveDay);\r\n  const body = $(\"#dy-body\");\r\n  body.addEventListener(\"input\", (ev) => { const tr = ev.target.closest(\"tr[data-cid]\"); if (tr) { paintDayRow(tr); countDay(); } });\r\n  body.addEventListener(\"keydown\", (ev) => {\r\n    if (ev.key !== \"Enter\" || !ev.target.matches(\"input[data-f]\")) return;\r\n    ev.preventDefault();\r\n    const nxt = ev.target.closest(\"tr\").nextElementSibling;\r\n    const t = nxt ? nxt.querySelector(`input[data-f=\"${ev.target.dataset.f}\"]`) : null;\r\n    if (t) { t.focus(); t.select(); } else $(\"#dy-save\").focus();\r\n  });\r\n  renderDay();\r\n}\r\nasync function renderDay() {\r\n  const date = DY.date;\r\n  $(\"#dy-date\").value = date;\r\n  $(\"#dy-next\").disabled = date >= todayLocal();\r\n  const [y, m, d] = date.split(\"-\");\r\n  $(\"#dy-long\").textContent = `${d}/${m}/${y.slice(2)}`;\r\n  const box = $(\"#dy-body\");\r\n  try {\r\n    const { data } = await api(\"/api/entries?date=\" + date);\r\n    if (!data.length) {\r\n      box.innerHTML = `<div class=\"empty\"><strong>Nenhum criativo ativo</strong><span>Cadastre um criativo ou mude o status para Ativo/Escalando.</span><a class=\"btn\" href=\"#/cadastro\">Cadastrar criativo</a></div>`;\r\n      $(\"#dy-save\").disabled = true; $(\"#dy-count\").textContent = \"\";\r\n      return;\r\n    }\r\n    const cell = (f, val, mode, ph) => `<td><input class=\"ci\" data-f=\"${f}\" inputmode=\"${mode}\" value=\"${esc(val)}\" placeholder=\"${esc(ph)}\"></td>`;\r\n    box.innerHTML = `<table class=\"tbl daytbl\"><thead><tr><th>Criativo</th><th class=\"num\">Invest. (R$)</th><th class=\"num\">Vendas</th><th class=\"num\">Fatur. (R$)</th><th class=\"num\">Cliques Meta</th><th class=\"num\">Cliques Shopee</th><th class=\"num\">Custo</th><th class=\"num\">Lucro</th><th class=\"num\">CPC Meta</th><th class=\"num\">CPC Shopee</th><th>Saúde</th></tr></thead><tbody>${data.map((r) => {\r\n      const e = r.entry;\r\n      return `<tr data-cid=\"${r.creative.id}\" data-tax=\"${r.tax_rate}\" data-dia1=\"${esc(r.dia1 ?? \"\")}\"><td><div class=\"nm\">${esc(r.creative.name)}</div><div class=\"sub\">${esc(r.creative.product || \"—\")}</div></td>`\r\n        + cell(\"invest\", e ? fmtInputCents(e.investment_cents) : \"\", \"decimal\", \"0,00\")\r\n        + cell(\"sales\", e ? String(e.sales) : \"\", \"numeric\", \"0\")\r\n        + cell(\"rev\", e && e.revenue_cents != null ? fmtInputCents(e.revenue_cents) : \"\", \"decimal\", \"pendente\")\r\n        + cell(\"clM\", e ? String(e.clicks_meta) : \"\", \"numeric\", \"0\")\r\n        + cell(\"clS\", e ? String(e.clicks_shopee) : \"\", \"numeric\", \"0\")\r\n        + `<td class=\"calc\" data-c=\"cost\">—</td><td class=\"calc\" data-c=\"profit\">—</td><td class=\"calc\" data-c=\"cpcM\">—</td><td class=\"calc\" data-c=\"cpcS\">—</td><td class=\"mut\" data-c=\"health\">—</td></tr>`;\r\n    }).join(\"\")}</tbody></table>`;\r\n    $$(\"#dy-body tr[data-cid]\").forEach(paintDayRow);\r\n    countDay();\r\n    const w = $(\"#dy-warn\"); if (w) w.hidden = true;\r\n  } catch {\r\n    box.innerHTML = `<div class=\"empty\"><strong>Não foi possível carregar o dia</strong></div>`;\r\n  }\r\n}\r\nfunction paintDayRow(tr) {\r\n  const tax = Number(tr.dataset.tax || 0.1386);\r\n  const date = DY.date;\r\n  const dia1 = tr.dataset.dia1 || null;\r\n  const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\r\n  const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\r\n  const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\r\n  const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\r\n  const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\r\n  const invC = inv == null ? 0 : inv;\r\n  const salesN = sales == null ? 0 : sales;\r\n  const clMN = clM == null ? 0 : clM;\r\n  const clSN = clS == null ? 0 : clS;\r\n  const bad = [inv, sales, clM, clS].some((v) => typeof v === \"number\" && Number.isNaN(v)) || (rev != null && Number.isNaN(rev));\r\n  // Módulo único de cálculo (spec #6): custo/lucro/CPCs/pendente vêm do Calc.\r\n  const row = bad ? null : Calc.calcRow({ date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax });\r\n  const cost = row ? row.cost_cents : null;\r\n  const isPending = row ? row.is_pending : false;\r\n  const profit = row ? row.profit_cents : null;\r\n  const cpcM = row ? row.cpc_meta_cents : null;\r\n  const cpcS = row ? row.cpc_shopee_cents : null;\r\n  $('[data-c=\"cost\"]', tr).textContent = Calc.formatBRL(cost);\r\n  const pEl = $('[data-c=\"profit\"]', tr);\r\n  pEl.textContent = isPending ? \"pendente\" : Calc.formatBRL(profit);\r\n  pEl.className = \"calc\" + (profit == null || isPending ? \"\" : profit >= 0 ? \" prof good\" : \" prof bad\");\r\n  $('[data-c=\"cpcM\"]', tr).textContent = Calc.formatCPC(cpcM);\r\n  $('[data-c=\"cpcS\"]', tr).textContent = Calc.formatCPC(cpcS);\r\n  const hEl = $('[data-c=\"health\"]', tr);\r\n  const dayForSignal = { date, investment_cents: invC, sales: salesN, revenue_cents: rev, clicks_meta: clMN, clicks_shopee: clSN, tax_rate: tax };\r\n  if (bad || !Calc.hasMovement(dayForSignal)) { hEl.textContent = \"—\"; return; }\r\n  try {\r\n    const isDia1 = !dia1 || date <= dia1;\r\n    const sig = Calc.evaluateDay(dayForSignal, isDia1);\r\n    hEl.textContent = sig.saude === \"atencao\" ? `Atenção · ${sig.motivo ?? \"\"}` : (sig.motivo ?? \"Saudável\");\r\n  } catch { hEl.textContent = \"—\"; }\r\n}\r\nconst rowFilled = (tr) => [\"invest\", \"sales\", \"rev\", \"clM\", \"clS\"].some((f) => $('[data-f=\"' + f + '\"]', tr).value.trim() !== \"\");\r\nfunction countDay() {\r\n  const rows = $$(\"#dy-body tr[data-cid]\");\r\n  if (!rows.length) return;\r\n  const n = rows.filter(rowFilled).length;\r\n  $(\"#dy-count\").textContent = `${n} de ${rows.length} preenchidos`;\r\n  $(\"#dy-save\").disabled = n === 0;\r\n}\r\nasync function saveDay() {\r\n  const rows = $$(\"#dy-body tr[data-cid]\");\r\n  const entries = [];\r\n  $$(\"#dy-body .ci.bad\").forEach((i) => i.classList.remove(\"bad\"));\r\n  for (const tr of rows) {\r\n    if (!rowFilled(tr)) continue;\r\n    const cid = Number(tr.dataset.cid);\r\n    const inv = Calc.parseMoedaParaCentavos($('[data-f=\"invest\"]', tr).value);\r\n    const rev = Calc.parseMoedaParaCentavos($('[data-f=\"rev\"]', tr).value);\r\n    const sales = Calc.parseInteiro($('[data-f=\"sales\"]', tr).value);\r\n    const clM = Calc.parseInteiro($('[data-f=\"clM\"]', tr).value);\r\n    const clS = Calc.parseInteiro($('[data-f=\"clS\"]', tr).value);\r\n    const name = $(\".nm\", tr).textContent;\r\n    const mark = (f) => $('[data-f=\"' + f + '\"]', tr).classList.add(\"bad\");\r\n    let bad = false;\r\n    for (const [f, v] of [[\"invest\", inv], [\"sales\", sales], [\"rev\", rev], [\"clM\", clM], [\"clS\", clS]]) {\r\n      if (typeof v === \"number\" && Number.isNaN(v)) { mark(f); bad = true; }\r\n      if (typeof v === \"number\" && v != null && v < 0) { mark(f); bad = true; }\r\n    }\r\n    for (const [f, v] of [[\"sales\", sales], [\"clM\", clM], [\"clS\", clS]]) {\r\n      if (typeof v === \"number\" && v != null && !Number.isInteger(v)) { mark(f); bad = true; }\r\n    }\r\n    if (bad) { toast(`Confira os números de ${name}.`); return; }\r\n    entries.push({ creative_id: cid, investment_cents: inv ?? 0, sales: sales ?? 0, revenue_cents: rev, clicks_meta: clM ?? 0, clicks_shopee: clS ?? 0 });\r\n  }\r\n  if (!entries.length) { toast(\"Preencha ao menos um criativo.\"); return; }\r\n  try {\r\n    const { warnings } = await api(\"/api/entries/bulk\", { method: \"POST\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ date: DY.date, entries }) });\r\n    const w = $(\"#dy-warn\");\r\n    if (warnings?.length) { w.textContent = warnings.join(\" \"); w.hidden = false; }\r\n    else if (w) w.hidden = true;\r\n    toast(`${entries.length} ${entries.length === 1 ? \"lançamento salvo\" : \"lançamentos salvos\"} em ${fDate(DY.date)}`);\r\n    renderDay();\r\n  } catch (e) {\r\n    toast(e.body?.error === \"encerrado_sem_lancamento\" ? \"Criativo encerrado não recebe lançamentos.\" : \"Não foi possível salvar. Confira os números (nada negativo; vendas/cliques inteiros).\");\r\n  }\r\n}\r\n\r\n// ---------- Dashboard de decisão (T5) ----------\r\n// Filtros: período, Criativos, status, produto, decisão. Resumo com variação\r\n// contra o período anterior + aviso de pendentes. Gráfico diário SVG\r\n// (custo, faturamento, lucro/prejuízo, faixa nos dias pendentes).\r\n// Tabela de decisão ordenável com clique abrindo o detalhe.\r\nconst D = { preset: \"30d\", from: \"\", to: \"\", ids: new Set(), status: \"all\", product: \"all\", decision: \"all\", sort: { k: \"profit\", dir: -1 }, data: null, products: [] };\r\nconst PRESETS = [[\"today\",\"Hoje\"],[\"yesterday\",\"Ontem\"],[\"7d\",\"Últimos 7 dias\"],[\"14d\",\"Últimos 14 dias\"],[\"30d\",\"Últimos 30 dias\"],[\"month\",\"Este mês\"],[\"lastmonth\",\"Mês passado\"],[\"all\",\"Todo o período\"],[\"custom\",\"Personalizado\"]];\r\nfunction dAddDays(iso, n) { const [y,m,d] = iso.split(\"-\").map(Number); return new Date(Date.UTC(y,m-1,d+n)).toISOString().slice(0,10); }\r\nfunction dPresetRange() {\r\n  const t = todayLocal();\r\n  switch (D.preset) {\r\n    case \"today\": return [t, t];\r\n    case \"yesterday\": return [dAddDays(t,-1), dAddDays(t,-1)];\r\n    case \"7d\": return [dAddDays(t,-6), t];\r\n    case \"14d\": return [dAddDays(t,-13), t];\r\n    case \"30d\": return [dAddDays(t,-29), t];\r\n    case \"month\": return [t.slice(0,8)+\"01\", t];\r\n    case \"lastmonth\": { const first = t.slice(0,8)+\"01\"; const [y,m] = first.split(\"-\").map(Number); const prev = new Date(Date.UTC(y,m-2,1)); const pf = prev.toISOString().slice(0,10); return [pf.slice(0,8)+\"01\", dAddDays(first,-1)]; }\r\n    case \"all\": return [null, null];\r\n    default: return [D.from || t, D.to || t];\r\n  }\r\n}\r\nfunction deltaHtml(cur, prev, invert) {\r\n  if (cur == null || prev == null) return \"\";\r\n  if (prev === 0) return cur === 0 ? '<span class=\"dl n\">= estável</span>' : \"\";\r\n  const p = (cur - prev) / Math.abs(prev) * 100;\r\n  if (Math.abs(p) < 0.5) return '<span class=\"dl n\">= estável</span>';\r\n  const up = p > 0;\r\n  const good = invert ? !up : up;\r\n  return `<span class=\"dl ${good ? \"g\" : \"b\"}\">${up ? \"▲\" : \"▼\"} ${Math.abs(p).toLocaleString(\"pt-BR\",{maximumFractionDigits:0})}%</span>`;\r\n}\r\nasync function pageDashboard() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Dashboard</h1><p class=\"sub\" id=\"dash-sub\">Decida olhando o painel</p></div><a class=\"btn\" href=\"#/lancamento\">Lançar dados do dia</a></div>\r\n  <div class=\"fb\" role=\"group\" aria-label=\"Filtros do dashboard\">\r\n    <div class=\"dd\" id=\"dd-period\"><button class=\"ctl\" type=\"button\" id=\"dd-period-btn\" aria-haspopup=\"true\">📅 <span id=\"lbl-period\">Período</span></button>\r\n      <div class=\"dd-menu\" id=\"dd-period-menu\">${PRESETS.filter((p)=>p[0]!==\"custom\").map((p)=>`<button type=\"button\" class=\"dd-item\" data-preset=\"${p[0]}\">${p[1]}</button>`).join(\"\")}<div style=\"display:flex;gap:6px;margin-top:6px\"><label>De <input type=\"date\" class=\"in sm\" id=\"f-from\"></label><label>Até <input type=\"date\" class=\"in sm\" id=\"f-to\"></label></div></div></div>\r\n    <div class=\"dd\" id=\"dd-cr\"><button class=\"ctl\" type=\"button\">Criativo: <span id=\"lbl-cr\">Todos</span></button>\r\n      <div class=\"dd-menu\" style=\"min-width:280px\"><input class=\"in sm\" style=\"width:100%\" id=\"cr-q\" placeholder=\"Buscar criativo…\" aria-label=\"Buscar criativo\"><div class=\"dd-list\" id=\"cr-list\"></div><div><button class=\"lnk\" type=\"button\" id=\"cr-clear\">Limpar seleção</button></div></div></div>\r\n    <label class=\"ctl\">Status <select id=\"f-status\"><option value=\"all\">Todos</option>${Object.entries(STATUS).map(([k,v])=>`<option value=\"${k}\">${v}</option>`).join(\"\")}</select></label>\r\n    <label class=\"ctl\">Produto <select id=\"f-product\"><option value=\"all\">Todos</option></select></label>\r\n    <label class=\"ctl\">Decisão <select id=\"f-dec\"><option value=\"all\">Todas</option><option value=\"saudavel\">Saudável</option><option value=\"atencao\">Atenção</option><option value=\"escalando\">Escalando</option><option value=\"pausado\">Pausado</option><option value=\"encerrado\">Encerrado</option><option value=\"sem_dados\">Sem dados</option></select></label>\r\n    <button class=\"lnk\" type=\"button\" id=\"f-clear\" hidden>Limpar filtros</button>\r\n  </div>\r\n  <div id=\"dash-res\"><div class=\"panel\"><div class=\"panel-b mut\">Carregando…</div></div></div>`;\r\n  try {\r\n    const { data } = await api(\"/api/creatives?sort=name\");\r\n    D.products = [...new Set(data.map((c)=>c.product).filter(Boolean))].sort((a,b)=>a.localeCompare(b,\"pt-BR\"));\r\n    const sel = $(\"#f-product\");\r\n    sel.innerHTML = `<option value=\"all\">Todos</option>` + D.products.map((p)=>`<option>${esc(p)}</option>`).join(\"\");\r\n    sel.value = D.product;\r\n    const list = $(\"#cr-list\");\r\n    list.innerHTML = data.map((c)=>`<label class=\"dd-opt\" data-name=\"${esc(c.name.toLowerCase())}\"><input type=\"checkbox\" value=\"${c.id}\" ${D.ids.has(c.id)?\"checked\":\"\"}><span>${esc(c.name)}</span><small>${STATUS[c.status]??c.status}</small></label>`).join(\"\");\r\n  } catch {}\r\n  $(\"#f-status\").value = D.status; $(\"#f-dec\").value = D.decision;\r\n  const btn = $(\"#dd-period-btn\");\r\n  btn.addEventListener(\"click\", () => $(\"#dd-period\").classList.toggle(\"open\"));\r\n  $(\"#dd-period-menu\").addEventListener(\"click\", (e) => { const it = e.target.closest(\"[data-preset]\"); if (!it) return; D.preset = it.dataset.preset; $(\"#dd-period\").classList.remove(\"open\"); loadDashboard(); });\r\n  const range = () => { D.preset = \"custom\"; D.from = $(\"#f-from\").value; D.to = $(\"#f-to\").value; loadDashboard(); };\r\n  $(\"#f-from\").addEventListener(\"change\", range); $(\"#f-to\").addEventListener(\"change\", range);\r\n  const crBtn = $(\"#dd-cr .ctl\");\r\n  crBtn.addEventListener(\"click\", () => $(\"#dd-cr\").classList.toggle(\"open\"));\r\n  $(\"#cr-list\").addEventListener(\"change\", (e) => { const id = Number(e.target.value); if (e.target.checked) D.ids.add(id); else D.ids.delete(id); loadDashboard(); });\r\n  $(\"#cr-q\").addEventListener(\"input\", (e) => { const q = e.target.value.trim().toLowerCase(); $$(\"#cr-list .dd-opt\").forEach((o)=>{ o.hidden = q && !o.dataset.name.includes(q); }); });\r\n  $(\"#cr-clear\").addEventListener(\"click\", () => { D.ids.clear(); loadDashboard(); });\r\n  $(\"#f-status\").addEventListener(\"change\", (e) => { D.status = e.target.value; loadDashboard(); });\r\n  $(\"#f-product\").addEventListener(\"change\", (e) => { D.product = e.target.value; loadDashboard(); });\r\n  $(\"#f-dec\").addEventListener(\"change\", (e) => { D.decision = e.target.value; loadDashboard(); });\r\n  $(\"#f-clear\").addEventListener(\"click\", () => { Object.assign(D, { preset:\"30d\", from:\"\", to:\"\", status:\"all\", product:\"all\", decision:\"all\" }); D.ids.clear(); D.sort = { k:\"profit\", dir:-1 }; pageDashboard(); });\r\n  $(\"#dash-res\").addEventListener(\"click\", (e) => {\r\n    const th = e.target.closest(\"th[data-sort]\");\r\n    if (th) { const k = th.dataset.sort; D.sort = { k, dir: D.sort.k === k ? -D.sort.dir : -1 }; renderDashTable(); return; }\r\n    const tr = e.target.closest(\"tr[data-id]\");\r\n    if (tr) location.hash = \"#/criativo/\" + tr.dataset.id;\r\n    if (e.target.closest(\"[data-reset]\")) $(\"#f-clear\").click();\r\n  });\r\n  document.addEventListener(\"click\", (e) => { if (!e.target.closest(\".dd\")) $$(\".dd.open\").forEach((d)=>d.classList.remove(\"open\")); }, { once: true });\r\n  await loadDashboard();\r\n}\r\nasync function loadDashboard() {\r\n  const box = $(\"#dash-res\");\r\n  try {\r\n    const [from, to] = dPresetRange();\r\n    const qs = new URLSearchParams();\r\n    if (D.preset === \"all\") qs.set(\"all\", \"1\");\r\n    else { qs.set(\"from\", from); qs.set(\"to\", to); }\r\n    if (D.ids.size) qs.set(\"creatives\", [...D.ids].join(\",\"));\r\n    if (D.status !== \"all\") qs.set(\"status\", D.status);\r\n    if (D.product !== \"all\") qs.set(\"product\", D.product);\r\n    if (D.decision !== \"all\") qs.set(\"decision\", D.decision);\r\n    const { data, warnings } = await api(\"/api/dashboard?\" + qs.toString());\r\n    D.data = { ...data, warnings };\r\n    if (D.preset !== \"all\") { $(\"#f-from\").value = data.period.from; $(\"#f-to\").value = data.period.to; D.from = data.period.from; D.to = data.period.to; }\r\n    const lbl = PRESETS.find((p)=>p[0]===D.preset);\r\n    $(\"#lbl-period\").textContent = D.preset === \"all\" ? \"Todo o período\" : `${lbl ? lbl[1] : \"Personalizado\"} · ${fDate(data.period.from)}–${fDate(data.period.to)}`;\r\n    $(\"#lbl-cr\").textContent = !D.ids.size ? \"Todos\" : D.ids.size === 1 ? (data.creatives.find((c)=>D.ids.has(c.creative.id))?.creative.name ?? \"1 selecionado\") : `${D.ids.size} selecionados`;\r\n    $(\"#f-clear\").hidden = D.preset === \"30d\" && !D.ids.size && D.status === \"all\" && D.product === \"all\" && D.decision === \"all\";\r\n    renderDashboard();\r\n  } catch {\r\n    if (box) box.innerHTML = `<div class=\"panel\"><div class=\"empty\"><strong>Não foi possível carregar o dashboard</strong></div></div>`;\r\n  }\r\n}\r\nfunction renderDashboard() {\r\n  const d = D.data;\r\n  if (!d) return;\r\n  if (!d.creatives.length) {\r\n    $(\"#dash-res\").innerHTML = `<div class=\"panel\"><div class=\"empty\"><strong>Nenhum lançamento encontrado</strong><span>Não há dados neste período com os filtros escolhidos.</span><button class=\"btn ghost\" type=\"button\" data-reset>Limpar filtros</button></div></div>`;\r\n    return;\r\n  }\r\n  const t = d.totals, p = d.previousTotals;\r\n  const profCls = t.profit_cents == null ? \"\" : t.profit_cents >= 0 ? \"good\" : \"bad\";\r\n  const kpi = (lbl, big, sub, dl) => `<div class=\"kpi\"><div class=\"lbl\">${lbl}</div><div class=\"big ${profCls && lbl.includes(\"Lucro\") ? profCls : \"\"}\">${big}</div><div class=\"sub2\">${sub} ${dl ?? \"\"}</div></div>`;\r\n  const pendNote = t.has_pending ? `<div class=\"warnbox\">⚠ ${esc((d.warnings||[]).join(\" \") || `${t.pending_days} dia(s) com faturamento pendente — fora do lucro até preencher.`)} </div>` : \"\";\r\n  $(\"#dash-res\").innerHTML = `\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <div style=\"display:flex;gap:16px;align-items:baseline;flex-wrap:wrap;margin-bottom:12px\"><span class=\"mut\">Lucro no período</span><strong class=\"prof ${profCls}\" style=\"font-size:28px\">${t.profit_cents == null ? (t.has_pending ? \"pendente\" : \"—\") : fBRL(t.profit_cents)}</strong>${deltaHtml(t.profit_cents, p?.profit_cents ?? null)}${p ? '<span class=\"mut\">vs período anterior</span>' : \"\"}</div>\r\n    <div class=\"kpis\">\r\n      ${kpi(\"Investimento\", fBRL(t.investment_cents), `custo ${fBRL(t.cost_cents)}`, deltaHtml(t.investment_cents, p?.investment_cents ?? null, true))}\r\n      ${kpi(\"Faturamento\", t.costClosed_cents > 0 ? fBRL(t.revenue_cents) : \"—\", t.has_pending ? `${t.pending_days} dia(s) pendente(s)` : \"\", deltaHtml(t.revenue_cents, p?.revenue_cents ?? null))}\r\n      ${kpi(\"Vendas\", String(t.sales), \"\", deltaHtml(t.sales, p?.sales ?? null))}\r\n      ${kpi(\"ROAS-equiv.\", t.roas_equivalente == null ? \"—\" : Calc.formatRoas(t.roas_equivalente), \"fatur ÷ custo\", deltaHtml(t.roas_equivalente, p?.roas_equivalente ?? null))}\r\n      ${kpi(\"CPC Meta\", Calc.formatCPC(t.cpc_meta_cents), \"invest ÷ cliques\", deltaHtml(t.cpc_meta_cents, p?.cpc_meta_cents ?? null, true))}\r\n      ${kpi(\"CPC Shopee\", Calc.formatCPC(t.cpc_shopee_cents), \"invest ÷ cliques\", deltaHtml(t.cpc_shopee_cents, p?.cpc_shopee_cents ?? null, true))}\r\n    </div>\r\n    ${pendNote}\r\n  </div></section>\r\n  <section class=\"panel\"><div class=\"panel-h\"><h2>Evolução diária</h2><span class=\"mut\">custo · faturamento · lucro/prejuízo · faixa nos dias pendentes</span></div><div class=\"panel-b\" id=\"chart-box\"></div></section>\r\n  <section class=\"panel\"><div class=\"panel-h\"><h2>Decisão por criativo</h2><span class=\"mut\">clique abre o detalhe</span></div><div class=\"scroll\" id=\"dash-tbl\"></div>\r\n  <div class=\"foot-note\">Ordene por lucro, ROAS-equiv., custo ou vendas clicando no cabeçalho. A cor vem do Sinal (régua + Status + Motivo), nunca do ROAS.</div></section>`;\r\n  drawChart($(\"#chart-box\"), d.daily);\r\n  renderDashTable();\r\n}\r\nfunction renderDashTable() {\r\n  const d = D.data;\r\n  if (!d) return;\r\n  const rows = [...d.creatives].sort((x, y) => {\r\n    const g = (r) => ({ profit: r.totals.profit_cents, roas: r.totals.roas_equivalente, cost: r.totals.cost_cents, sales: r.totals.sales })[D.sort.k];\r\n    const a = g(x), b = g(y);\r\n    if (a == null && b == null) return 0; if (a == null) return 1; if (b == null) return -1;\r\n    return (a - b) * D.sort.dir;\r\n  });\r\n  const th = (k, label) => `<th class=\"num\" data-sort=\"${k}\">${label}${D.sort.k === k ? `<span class=\"ar\">${D.sort.dir < 0 ? \"↓\" : \"↑\"}</span>` : \"\"}</th>`;\r\n  $(\"#dash-tbl\").innerHTML = `<table class=\"tbl\"><thead><tr><th>Criativo</th><th>Status</th><th>Saúde</th>${th(\"profit\",\"Lucro\")}${th(\"roas\",\"ROAS-equiv.\")}${th(\"cost\",\"Custo\")}${th(\"sales\",\"Vendas\")}<th>Motivo</th></tr></thead><tbody>${rows.map((r) => {\r\n    const pc = profitClass(r.totals.profit_cents);\r\n    return `<tr class=\"click\" data-id=\"${r.creative.id}\"><td><div class=\"nm\">${esc(r.creative.name)}</div><div class=\"sub\">${esc(r.creative.product||\"—\")}</div></td><td>${chipFor(r.health)}</td><td>${rulerFor(r.health)}</td><td class=\"num prof ${pc}\">${r.totals.profit_cents == null ? (r.totals.has_pending ? \"pendente\" : \"—\") : fBRL(r.totals.profit_cents)}</td><td class=\"num\">${r.totals.roas_equivalente == null ? \"—\" : Calc.formatRoas(r.totals.roas_equivalente)}</td><td class=\"num\">${fBRL(r.totals.cost_cents)}</td><td class=\"num\">${r.totals.sales}</td><td class=\"mut\">${esc(r.health.motivo ?? \"—\")}</td></tr>`;\r\n  }).join(\"\")}</tbody></table>`;\r\n}\r\nfunction drawChart(box, days) {\r\n  if (!box) return;\r\n  const W = Math.max(box.clientWidth || 600, 320), H = 220, P = { l: 56, r: 12, t: 12, b: 26 };\r\n  const iw = W - P.l - P.r, ih = H - P.t - P.b;\r\n  const vals = [];\r\n  for (const d of days) { if (d.empty) continue; vals.push(d.cost_cents, d.revenue_cents ?? 0, d.profit_cents ?? 0); }\r\n  const max = Math.max(1, ...vals.map((v)=>Math.abs(v)));\r\n  const n = days.length;\r\n  const x = (i) => P.l + (n === 1 ? iw / 2 : (i / (n - 1)) * iw);\r\n  const y = (v) => P.t + ih / 2 - (v / max) * (ih / 2 - 4);\r\n  const bw = n ? Math.min(18, iw / Math.max(n,1) * 0.4) : 8;\r\n  let s = `<svg class=\"chart\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Gráfico diário\">`;\r\n  s += `<line x1=\"${P.l}\" y1=\"${y(0)}\" x2=\"${W-P.r}\" y2=\"${y(0)}\" stroke=\"#D8DFDC\"/>`;\r\n  days.forEach((d, i) => {\r\n    if (d.pending && !d.empty) s += `<rect x=\"${x(i)-bw}\" y=\"${P.t}\" width=\"${bw*2}\" height=\"${ih}\" fill=\"#F6E8BE\" opacity=\"0.55\"><title>${fDate(d.date)} · pendente</title></rect>`;\r\n  });\r\n  days.forEach((d, i) => {\r\n    if (d.empty) return;\r\n    const p = d.profit_cents ?? 0;\r\n    const y0 = y(0), y1 = y(p);\r\n    s += `<rect x=\"${x(i)-bw/2}\" y=\"${Math.min(y0,y1)}\" width=\"${bw}\" height=\"${Math.max(2,Math.abs(y1-y0))}\" fill=\"${p >= 0 ? \"#2FBF7A\" : \"#E5595B\"}\"><title>${fDate(d.date)} · lucro ${d.profit_cents == null ? \"pendente\" : (d.profit_cents/100).toLocaleString(\"pt-BR\",{style:\"currency\",currency:\"BRL\"})}</title></rect>`;\r\n  });\r\n  const line = (get, color) => {\r\n    const pts = days.map((d, i) => d.empty ? null : `${x(i).toFixed(1)},${y(get(d) ?? 0).toFixed(1)}`).filter(Boolean);\r\n    if (pts.length < 2) return \"\";\r\n    return `<polyline points=\"${pts.join(\" \")}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2\"/>`;\r\n  };\r\n  s += line((d)=>d.cost_cents, \"#16201C\");\r\n  s += line((d)=>d.revenue_cents ?? 0, \"#0E76B8\");\r\n  days.forEach((d, i) => { if (i % Math.ceil(n/6) === 0) s += `<text x=\"${x(i)}\" y=\"${H-8}\" font-size=\"10\" text-anchor=\"middle\" fill=\"#647570\">${fDate(d.date)}</text>`; });\r\n  s += `<g font-size=\"11\"><circle cx=\"${P.l+6}\" cy=\"8\" r=\"4\" fill=\"#16201C\"/><text x=\"${P.l+14}\" y=\"12\" fill=\"#16201C\">Custo</text><circle cx=\"${P.l+70}\" cy=\"8\" r=\"4\" fill=\"#0E76B8\"/><text x=\"${P.l+78}\" y=\"12\" fill=\"#16201C\">Faturamento</text><rect x=\"${P.l+168}\" y=\"4\" width=\"10\" height=\"8\" fill=\"#2FBF7A\"/><rect x=\"${P.l+180}\" y=\"4\" width=\"10\" height=\"8\" fill=\"#E5595B\"/><text x=\"${P.l+194}\" y=\"12\" fill=\"#16201C\">Lucro/prejuízo</text></g>`;\r\n  s += `</svg>`;\r\n  box.innerHTML = s;\r\n}\r\n\r\n// ---------- Config: imposto + backup/export (T5) ----------\r\nasync function pageConfig() {\r\n  view().innerHTML = `\r\n  <div class=\"ph\"><div><h1>Configurações</h1><p class=\"sub\">Imposto, backup e dados</p></div></div>\r\n  <div class=\"cols\">\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <h2 style=\"margin:0 0 8px\">Imposto (%)</h2>\r\n    <p class=\"hint\">Taxa usada nos próximos lançamentos. Dias antigos ficam intactos (cada dia guarda a própria taxa).</p>\r\n    <div class=\"fld\"><label for=\"cfg-tax\">Taxa atual (%)</label><input class=\"in\" id=\"cfg-tax\" inputmode=\"decimal\" placeholder=\"13,86\"><span class=\"hint\">Aceita 13,86 ou 13.86 (= 13,86%).</span><div class=\"err-msg\" id=\"cfg-tax-err\" hidden></div></div>\r\n    <div class=\"actions\"><button class=\"btn\" id=\"cfg-save\" type=\"button\">Salvar imposto</button></div>\r\n  </div></section>\r\n  <section class=\"panel\"><div class=\"panel-b\">\r\n    <h2 style=\"margin:0 0 8px\">Backup e dados</h2>\r\n    <p class=\"hint\" id=\"cfg-path\">Caminho do arquivo: carregando…</p>\r\n    <div class=\"actions\"><button class=\"btn\" id=\"cfg-backup\" type=\"button\">Fazer backup agora</button><button class=\"btn ghost\" id=\"cfg-export\" type=\"button\">Exportar dados (JSON)</button></div>\r\n    <div style=\"height:12px\"></div>\r\n    <strong>Últimos backups (30 mantidos)</strong>\r\n    <ul class=\"recent\" id=\"cfg-backs\"><li class=\"mut\">Carregando…</li></ul>\r\n  </div></section>\r\n  </div>`;\r\n  try {\r\n    const [{ data: s }, info] = await Promise.all([api(\"/api/settings\"), api(\"/api/info\")]);\r\n    $(\"#cfg-tax\").value = (s.tax_rate * 100).toLocaleString(\"pt-BR\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\r\n    $(\"#cfg-path\").textContent = `Caminho do arquivo: ${info.data.dbPath} (pasta ${info.data.dataDir}) — backups diários em backups/, 30 últimos.`;\r\n  } catch { $(\"#cfg-path\").textContent = \"Não foi possível ler o caminho do arquivo.\"; }\r\n  $(\"#cfg-save\").addEventListener(\"click\", async () => {\r\n    const err = $(\"#cfg-tax-err\");\r\n    err.hidden = true;\r\n    try {\r\n      const { data } = await api(\"/api/settings\", { method: \"PUT\", headers: {\"content-type\":\"application/json\"}, body: JSON.stringify({ tax_rate: $(\"#cfg-tax\").value }) });\r\n      $(\"#cfg-tax\").value = (data.tax_rate * 100).toLocaleString(\"pt-BR\", { minimumFractionDigits: 2, maximumFractionDigits: 2 });\r\n      toast(`Imposto atualizado para ${(data.tax_rate*100).toLocaleString(\"pt-BR\")}% — dias antigos intactos.`);\r\n    } catch (e) { err.textContent = \"Valor inválido. Use algo como 13,86.\"; err.hidden = false; }\r\n  });\r\n  $(\"#cfg-backup\").addEventListener(\"click\", async () => {\r\n    try { const { data } = await api(\"/api/backup\", { method: \"POST\" }); toast(`Backup criado: ${data.file}`); await loadBacks(); }\r\n    catch { toast(\"Não foi possível criar o backup.\"); }\r\n  });\r\n  $(\"#cfg-export\").addEventListener(\"click\", async () => {\r\n    try {\r\n      const { data } = await api(\"/api/export\");\r\n      const blob = new Blob([JSON.stringify(data, null, 2)], { type: \"application/json\" });\r\n      const a = document.createElement(\"a\");\r\n      a.href = URL.createObjectURL(blob);\r\n      a.download = `gestor-export-${todayLocal()}.json`;\r\n      a.click();\r\n      setTimeout(() => URL.revokeObjectURL(a.href), 2000);\r\n      toast(\"Dados exportados.\");\r\n    } catch { toast(\"Não foi possível exportar.\"); }\r\n  });\r\n  async function loadBacks() {\r\n    try {\r\n      const { data } = await api(\"/api/backups\");\r\n      $(\"#cfg-backs\").innerHTML = data.length ? data.slice(0,30).map((b)=>`<li><span>${esc(b.file)}</span><span class=\"mut\">${b.size != null ? (b.size/1024).toLocaleString(\"pt-BR\",{maximumFractionDigits:0}) + \" KB\" : \"\"}</span></li>`).join(\"\") : `<li class=\"mut\">Nenhum backup ainda.</li>`;\r\n    } catch { $(\"#cfg-backs\").innerHTML = `<li class=\"mut\">—</li>`; }\r\n  }\r\n  await loadBacks();\r\n}\r\n\r\nfunction router() {\r\n  $$(\".nav a\").forEach((a) => a.removeAttribute(\"aria-current\"));\r\n  const h = location.hash || \"#/dashboard\";\r\n  if (h.startsWith(\"#/cadastro\")) { $('[data-nav=\"cadastro\"]').setAttribute(\"aria-current\",\"page\"); pageRegister(); }\r\n  else if (h.startsWith(\"#/criativo/\")) { $('[data-nav=\"criativos\"]').setAttribute(\"aria-current\",\"page\"); pageDetail(h.split(\"/\")[2]); }\r\n  else if (h.startsWith(\"#/lancamento\")) { $('[data-nav=\"lancamento\"]').setAttribute(\"aria-current\",\"page\"); pageDaily(); }\r\n  else if (h.startsWith(\"#/criativos\")) { $('[data-nav=\"criativos\"]').setAttribute(\"aria-current\",\"page\"); pageLibrary(); }\r\n  else if (h.startsWith(\"#/config\")) { $('[data-nav=\"config\"]').setAttribute(\"aria-current\",\"page\"); pageConfig(); }\r\n  else { $('[data-nav=\"dashboard\"]').setAttribute(\"aria-current\",\"page\"); pageDashboard(); }\r\n}\r\nwindow.addEventListener(\"hashchange\", router);\r\nrouter();\r\n</script>\r\n</body>\r\n</html>\r\n";
export const APP_VERSION = "0.1.0";
